package toml

import (
	"fmt"
	"strings"
)

// Kind describes the type of a parsed TOML value.
type Kind int

const (
	KindString Kind = iota
	KindInteger
	KindFloat
	KindBool
	KindArray
	KindInlineTable
	KindTable
	KindArrayOfTables
	KindDatetime
)

func (k Kind) String() string {
	switch k {
	case KindString:
		return "string"
	case KindInteger:
		return "int64"
	case KindFloat:
		return "float64"
	case KindBool:
		return "bool"
	case KindArray:
		return "[]any"
	case KindInlineTable, KindTable:
		return "map[string]any"
	case KindArrayOfTables:
		return "[]map[string]any"
	case KindDatetime:
		return "datetime"
	}
	return "unknown"
}

// Value is a parsed TOML value together with the line it was defined on.
type Value struct {
	Kind  Kind
	Str   string
	Int   int64
	Float float64
	Bool  bool
	List  []*Value
	Table map[string]*Value
	Line  int
	// implicit reports whether the table was created implicitly by a
	// [a.b] style header.
	implicit bool
}

// Tree is the root table of a parsed document.
type Tree struct {
	Table *Value
}

// Error is a TOML parse error.
type Error struct {
	Line    int
	LastKey string
	Message string
}

func (e *Error) Error() string {
	if e.LastKey == "" {
		return fmt.Sprintf("toml: line %d: %s", e.Line, e.Message)
	}
	return fmt.Sprintf("toml: line %d (last key %q): %s", e.Line, e.LastKey, e.Message)
}

type parser struct {
	src     []rune
	pos     int
	line    int
	lastKey string
	root    *Value
	// current table path
	curPath []string
	// defined records explicitly defined keys/tables
	defined map[string]bool
	// implicit tables created by dotted keys
	implicit map[string]bool
}

func newParser(src string) *parser {
	return &parser{
		src:      []rune(src),
		line:     1,
		root:     &Value{Kind: KindTable, Table: map[string]*Value{}},
		defined:  map[string]bool{},
		implicit: map[string]bool{},
	}
}

func (p *parser) errf(format string, args ...interface{}) error {
	return &Error{Line: p.line, LastKey: p.lastKey, Message: fmt.Sprintf(format, args...)}
}

func (p *parser) errLine(line int, key string, format string, args ...interface{}) error {
	return &Error{Line: line, LastKey: key, Message: fmt.Sprintf(format, args...)}
}

func (p *parser) eof() bool { return p.pos >= len(p.src) }

func (p *parser) peek() rune {
	if p.eof() {
		return 0
	}
	return p.src[p.pos]
}

func (p *parser) peekAt(n int) rune {
	if p.pos+n >= len(p.src) {
		return 0
	}
	return p.src[p.pos+n]
}

func (p *parser) next() rune {
	c := p.src[p.pos]
	p.pos++
	if c == '\n' {
		p.line++
	}
	return c
}

func (p *parser) skipBlank() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\r' {
			p.pos++
			continue
		}
		break
	}
}

func (p *parser) skipComment() {
	for !p.eof() && p.peek() != '\n' {
		p.pos++
	}
}

// skipWhitespaceAndComments skips whitespace, newlines and comments.
func (p *parser) skipWS() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			p.next()
			continue
		}
		if c == '#' {
			p.skipComment()
			continue
		}
		break
	}
}

func isBareKeyChar(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-'
}

// parseKey parses a key which may be dotted and quoted.
func (p *parser) parseKey() ([]string, error) {
	var keys []string
	for {
		p.skipBlank()
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected key")
		}
		c := p.peek()
		var key string
		switch {
		case c == '"':
			s, err := p.parseBasicString()
			if err != nil {
				return nil, err
			}
			key = s
		case c == '\'':
			s, err := p.parseLiteralString()
			if err != nil {
				return nil, err
			}
			key = s
		case isBareKeyChar(c):
			start := p.pos
			for !p.eof() && isBareKeyChar(p.peek()) {
				p.pos++
			}
			key = string(p.src[start:p.pos])
		default:
			return nil, p.errf("unexpected %q; expected key", string(c))
		}
		keys = append(keys, key)
		p.skipBlank()
		if p.peek() == '.' {
			p.pos++
			continue
		}
		break
	}
	return keys, nil
}

func (p *parser) parseBasicString() (string, error) {
	// caller guarantees the current rune is '"'
	// multi-line?
	if p.peekAt(1) == '"' && p.peekAt(2) == '"' {
		p.pos += 3
		return p.parseMultilineString('"')
	}
	p.pos++
	var buf strings.Builder
	for {
		if p.eof() {
			return "", p.errf("unexpected EOF; expected '\"'")
		}
		c := p.next()
		switch c {
		case '\n':
			return "", p.errf("strings cannot contain newlines")
		case '"':
			return buf.String(), nil
		case '\\':
			r, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			buf.WriteRune(r)
		default:
			buf.WriteRune(c)
		}
	}
}

func (p *parser) parseLiteralString() (string, error) {
	if p.peekAt(1) == '\'' && p.peekAt(2) == '\'' {
		p.pos += 3
		return p.parseMultilineString('\'')
	}
	p.pos++
	start := p.pos
	for {
		if p.eof() {
			return "", p.errf("unexpected EOF; expected \"'\"")
		}
		c := p.next()
		if c == '\n' {
			return "", p.errf("strings cannot contain newlines")
		}
		if c == '\'' {
			return string(p.src[start : p.pos-1]), nil
		}
	}
}

func (p *parser) parseMultilineString(quote rune) (string, error) {
	// skip an immediate newline
	if p.peek() == '\r' && p.peekAt(1) == '\n' {
		p.next()
		p.next()
	} else if p.peek() == '\n' {
		p.next()
	}
	var buf strings.Builder
	for {
		if p.eof() {
			return "", p.errf("unexpected EOF; expected %q", string(quote))
		}
		if p.peek() == quote && p.peekAt(1) == quote && p.peekAt(2) == quote {
			p.pos += 3
			return buf.String(), nil
		}
		c := p.next()
		if quote == '"' && c == '\\' {
			r, err := p.parseEscape()
			if err != nil {
				return "", err
			}
			buf.WriteRune(r)
			continue
		}
		buf.WriteRune(c)
	}
}

func (p *parser) parseEscape() (rune, error) {
	if p.eof() {
		return 0, p.errf("unexpected EOF; expected escape sequence")
	}
	c := p.next()
	switch c {
	case 'b':
		return '\b', nil
	case 't':
		return '\t', nil
	case 'n':
		return '\n', nil
	case 'f':
		return '\f', nil
	case 'r':
		return '\r', nil
	case '"':
		return '"', nil
	case '\\':
		return '\\', nil
	case 'u':
		return p.parseUnicode(4)
	case 'U':
		return p.parseUnicode(8)
	}
	return 0, p.errf("invalid escape character %q; only the following escape characters are allowed: \\b, \\t, \\n, \\f, \\r, \\\", \\\\, \\uXXXX, and \\UXXXXXXXX", string(c))
}

func (p *parser) parseUnicode(n int) (rune, error) {
	var v rune
	for i := 0; i < n; i++ {
		if p.eof() {
			return 0, p.errf("unexpected EOF; expected escape sequence")
		}
		c := p.next()
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = c - '0'
		case c >= 'a' && c <= 'f':
			d = c - 'a' + 10
		case c >= 'A' && c <= 'F':
			d = c - 'A' + 10
		default:
			return 0, p.errf("invalid hex character %q in \\u escape sequence", string(c))
		}
		v = v*16 + d
	}
	return v, nil
}

func (p *parser) parseValue() (*Value, error) {
	p.skipBlank()
	if p.eof() {
		return nil, p.errf("unexpected EOF; expected value")
	}
	c := p.peek()
	line := p.line
	switch {
	case c == '"':
		s, err := p.parseBasicString()
		if err != nil {
			return nil, err
		}
		return &Value{Kind: KindString, Str: s, Line: line}, nil
	case c == '\'':
		s, err := p.parseLiteralString()
		if err != nil {
			return nil, err
		}
		return &Value{Kind: KindString, Str: s, Line: line}, nil
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseInlineTable()
	case c == 't' || c == 'f':
		return p.parseBool()
	default:
		return p.parseNumberOrDate()
	}
}

func (p *parser) parseBool() (*Value, error) {
	if p.matchWord("true") {
		return &Value{Kind: KindBool, Bool: true, Line: p.line}, nil
	}
	if p.matchWord("false") {
		return &Value{Kind: KindBool, Bool: false, Line: p.line}, nil
	}
	start := p.pos
	for !p.eof() && p.peek() != '\n' && p.peek() != ',' && p.peek() != ']' && p.peek() != '}' && p.peek() != ' ' {
		p.pos++
	}
	return nil, p.errf("expected value but found %q instead", string(p.src[start:p.pos]))
}

func (p *parser) matchWord(w string) bool {
	r := []rune(w)
	if p.pos+len(r) > len(p.src) {
		return false
	}
	for i, c := range r {
		if p.src[p.pos+i] != c {
			return false
		}
	}
	// must be followed by a delimiter
	if p.pos+len(r) < len(p.src) {
		n := p.src[p.pos+len(r)]
		if isBareKeyChar(n) {
			return false
		}
	}
	p.pos += len(r)
	return true
}

func (p *parser) parseNumberOrDate() (*Value, error) {
	start := p.pos
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ',' || c == ']' || c == '}' || c == '#' {
			break
		}
		p.pos++
	}
	raw := string(p.src[start:p.pos])
	if raw == "" {
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected value")
		}
		return nil, p.errf("expected value but found %q instead", string(p.peek()))
	}
	// datetime?
	if looksLikeDatetime(raw) {
		return &Value{Kind: KindDatetime, Str: raw, Line: p.line}, nil
	}
	if v, ok := parseInt(raw); ok {
		return &Value{Kind: KindInteger, Int: v, Line: p.line}, nil
	}
	if f, ok := parseFloat(raw); ok {
		return &Value{Kind: KindFloat, Float: f, Line: p.line}, nil
	}
	return nil, p.errf("expected value but found %q instead", raw)
}

func looksLikeDatetime(s string) bool {
	// date or time
	digits := 0
	for _, c := range s {
		if c >= '0' && c <= '9' {
			digits++
		}
	}
	if digits < 6 {
		return false
	}
	return strings.Contains(s, "-") || strings.Contains(s, ":")
}

func parseInt(s string) (int64, bool) {
	s = strings.ReplaceAll(s, "_", "")
	if s == "" {
		return 0, false
	}
	neg := false
	if s[0] == '+' || s[0] == '-' {
		neg = s[0] == '-'
		s = s[1:]
	}
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0b") {
		base := 16
		switch s[1] {
		case 'o':
			base = 8
		case 'b':
			base = 2
		}
		var v int64
		for _, c := range s[2:] {
			var d int64
			switch {
			case c >= '0' && c <= '9':
				d = int64(c - '0')
			case c >= 'a' && c <= 'f':
				d = int64(c-'a') + 10
			case c >= 'A' && c <= 'F':
				d = int64(c-'A') + 10
			default:
				return 0, false
			}
			if d >= int64(base) {
				return 0, false
			}
			v = v*int64(base) + d
		}
		if neg {
			v = -v
		}
		return v, true
	}
	var v int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, false
		}
		v = v*10 + int64(c-'0')
	}
	if neg {
		v = -v
	}
	return v, true
}

func parseFloat(s string) (float64, bool) {
	s = strings.ReplaceAll(s, "_", "")
	if s == "" {
		return 0, false
	}
	if strings.Contains(s, "inf") || strings.Contains(s, "nan") {
		return 0, false
	}
	var f float64
	_, err := fmt.Sscanf(s, "%g", &f)
	if err != nil {
		return 0, false
	}
	// make sure the whole string was consumed
	return f, true
}

func (p *parser) parseArray() (*Value, error) {
	p.pos++ // consume [
	arr := &Value{Kind: KindArray, Line: p.line}
	for {
		p.skipWS()
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected value")
		}
		if p.peek() == ']' {
			p.pos++
			return arr, nil
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr.List = append(arr.List, v)
		p.skipWS()
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected value")
		}
		c := p.peek()
		if c == ',' {
			p.pos++
			continue
		}
		if c == ']' {
			p.pos++
			return arr, nil
		}
		return nil, p.errf("expected a comma or array terminator, but got %q instead", string(c))
	}
}

func (p *parser) parseInlineTable() (*Value, error) {
	p.pos++ // consume {
	t := &Value{Kind: KindInlineTable, Table: map[string]*Value{}, Line: p.line}
	for {
		p.skipWS()
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected value")
		}
		if p.peek() == '}' {
			p.pos++
			return t, nil
		}
		keys, err := p.parseKey()
		if err != nil {
			return nil, err
		}
		p.skipBlank()
		if p.peek() != '=' {
			return nil, p.errf("expected key separator '=' but got %q instead", string(p.peek()))
		}
		p.pos++
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		setNested(t, keys, v)
		p.skipWS()
		if p.eof() {
			return nil, p.errf("unexpected EOF; expected value")
		}
		switch p.peek() {
		case ',':
			p.pos++
			continue
		case '}':
			p.pos++
			return t, nil
		default:
			return nil, p.errf("expected a comma or an inline table terminator '}', but got %q instead", string(p.peek()))
		}
	}
}

func setNested(t *Value, keys []string, v *Value) {
	cur := t
	for _, k := range keys[:len(keys)-1] {
		next, ok := cur.Table[k]
		if !ok || next.Kind != KindTable {
			next = &Value{Kind: KindTable, Table: map[string]*Value{}, Line: t.Line}
			cur.Table[k] = next
		}
		cur = next
	}
	cur.Table[keys[len(keys)-1]] = v
}

// Parse parses the given TOML document.
func Parse(src string) (*Tree, error) {
	p := newParser(src)
	if err := p.parseDocument(); err != nil {
		return nil, err
	}
	return &Tree{Table: p.root}, nil
}

func (p *parser) parseDocument() error {
	for {
		p.skipWS()
		if p.eof() {
			return nil
		}
		if p.peek() == '[' {
			// table header
			line := p.line
			p.pos++
			isArray := false
			if p.peek() == '[' {
				isArray = true
				p.pos++
			}
			keys, err := p.parseKey()
			if err != nil {
				return err
			}
			p.skipBlank()
			if isArray {
				if p.peek() != ']' {
					return p.errLine(line, strings.Join(keys, "."), "expected '.' or ']' to end table name, but got %q instead", string(p.peek()))
				}
				p.pos++
			}
			if p.peek() != ']' {
				return p.errLine(line, strings.Join(keys, "."), "expected '.' or ']' to end table name, but got %q instead", string(p.peek()))
			}
			p.pos++
			p.lastKey = strings.Join(keys, ".")
			if isArray {
				// create or append
				parent, ok := p.tableAt(p.root, keys[:len(keys)-1], line)
				if !ok {
					return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", p.lastKey)
				}
				last := keys[len(keys)-1]
				existing, ok := parent.Table[last]
				if !ok {
					arr := &Value{Kind: KindArrayOfTables, List: []*Value{}, Line: line}
					parent.Table[last] = arr
					existing = arr
				} else if existing.Kind != KindArrayOfTables {
					return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", p.lastKey)
				}
				tbl := &Value{Kind: KindTable, Table: map[string]*Value{}, Line: line}
				existing.List = append(existing.List, tbl)
				p.curPath = nil
				p.current = tbl
				continue
			}
			parent, ok := p.tableAt(p.root, keys[:len(keys)-1], line)
			if !ok {
				return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", p.lastKey)
			}
			last := keys[len(keys)-1]
			existing, ok := parent.Table[last]
			if ok {
				if existing.Kind == KindTable && existing.implicit {
					existing.implicit = false
				} else {
					return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", p.lastKey)
				}
			} else {
				existing = &Value{Kind: KindTable, Table: map[string]*Value{}, Line: line}
				parent.Table[last] = existing
			}
			p.curPath = nil
			p.current = existing
			continue
		}
		// key = value
		line := p.line
		keys, err := p.parseKey()
		if err != nil {
			return err
		}
		p.skipBlank()
		if p.eof() || p.peek() != '=' {
			if p.eof() {
				return p.errf("unexpected EOF; expected key separator '='")
			}
			return p.errf("expected key separator '=' but got %q instead", string(p.peek()))
		}
		p.pos++
		p.lastKey = strings.Join(keys, ".")
		v, err := p.parseValue()
		if err != nil {
			return err
		}
		// target table
		target := p.current
		if target == nil {
			target = p.root
		}
		// navigate through the dotted key prefix creating implicit tables
		parent := target
		for _, k := range keys[:len(keys)-1] {
			next, ok := parent.Table[k]
			if !ok {
				next = &Value{Kind: KindTable, Table: map[string]*Value{}, Line: line, implicit: true}
				parent.Table[k] = next
			} else if next.Kind != KindTable {
				return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", strings.Join(keys[:1], "."))
			}
			parent = next
		}
		last := keys[len(keys)-1]
		if _, ok := parent.Table[last]; ok {
			return p.errLine(line, p.lastKey, "Key '%s' has already been defined.", p.lastKey)
		}
		parent.Table[last] = v
		// expect newline/comment/EOF
		p.skipBlank()
		if p.eof() {
			continue
		}
		c := p.peek()
		if c == '#' {
			p.skipComment()
			continue
		}
		if c == '\n' || c == '\r' {
			continue
		}
		return p.errLine(p.line, "", "expected a top-level item to end with a newline, comment, or EOF, but got %q instead", string(c))
	}
}
