// tableAt navigates the root table through the given key path, creating
// implicit tables when necessary. It returns false when a non-table value
// blocks the path.
func (p *parser) tableAt(root *Value, keys []string, line int) (*Value, bool) {
	cur := root
	for _, k := range keys {
