package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

// Position is a position in a file.
type Position struct {
	Filename string
	Offset   int
	Line     int
	Column   int
}

// FailurePosition holds the start and end position of a failure.
type FailurePosition struct {
	Start Position
	End   Position
}

// Failure represents an issue found by a rule.
type Failure struct {
	Severity        string
	Failure         string
	RuleName        string
	Category        string
	Position        FailurePosition
	Confidence      float64
	ReplacementLine string
}

// Arguments are the arguments passed to a rule from the configuration file.
type Arguments []interface{}

// Rule is the interface that all lint rules must implement.
type Rule interface {
	Name() string
	Category() string
	Apply(file *File, arguments Arguments) []Failure
}

// RuleConfig is the configuration of a single rule.
type RuleConfig struct {
	Severity  string
	Exclude   []string
	Arguments Arguments
	Disabled  bool
}

// Severity levels.
const (
	SeverityError   = "error"
	SeverityWarning = "warning"
)

// Config holds the configuration of the linter.
type Config struct {
	Severity       string
	Confidence     float64
	ErrorCode      int
	WarningCode    int
	EnableAllRules bool
	Exclude        []string
	Rules          map[string]*RuleConfig
}

// File holds all the data about a file that is being linted.
type File struct {
	Name        string
	Content     []byte
	AST         *ast.File
	Fset        *token.FileSet
	PackageName string
	TypeInfo    *types.Info
	IsTest      bool

	// directives holds the state of the revive comment directives.
	directives *directives
}

// PositionOf returns the position of the given token position.
func (f *File) PositionOf(p token.Pos) token.Position {
	return f.Fset.Position(p)
}

// TypeOf returns the type of the given expression.
func (f *File) TypeOf(e ast.Expr) types.Type {
	if f.TypeInfo == nil {
		return nil
	}
	return f.TypeInfo.TypeOf(e)
}

// Uses returns the type information for the given identifier.
func (f *File) Uses(id *ast.Ident) types.Type {
	if f.TypeInfo == nil {
		return nil
	}
	if o, ok := f.TypeInfo.Uses[id]; ok {
		return o.Type()
	}
	return nil
}

// Defs returns the type information for the given definition.
func (f *File) Defs(id *ast.Ident) types.Type {
	if f.TypeInfo == nil {
		return nil
	}
	if o, ok := f.TypeInfo.Defs[id]; ok {
		return o.Type()
	}
	return nil
}

// OffsetOf converts the given token position into a byte offset.
func (f *File) OffsetOf(p token.Pos) int {
	if f.Fset == nil {
		return 0
	}
	return f.Fset.Position(p).Offset
}
GOEOF
cat > internal/lint/directives.go <<'GOEOF'
package lint

import (
	"go/ast"
	"strings"
)

// directiveAction is the action of a revive comment directive.
type directiveAction int

const (
	// directiveNone means that the comment is a revive comment but it does not
	// change the state of the linter.
	directiveNone directiveAction = iota
	directiveDisable
	directiveEnable
	directiveDisableNextLine
	directiveEnableNextLine
)

type directive struct {
	line   int
	action directiveAction
	target string
}

// directives keeps track of the state of the revive comment directives of a
// file.
type directives struct {
	list []directive
}

func (d *directives) state(line int, rule string) bool {
	// disabled returns true when the given rule is disabled at the given line.
	disabled := false
	disableNextLineLine := -1
	disabledRules := map[string]bool{}
	enabledRules := map[string]bool{}
	allDisabled := false
	lastProcessed := -1
	for _, dir := range d.list {
		if dir.line > line {
			break
		}
		lastProcessed = dir.line
		switch dir.action {
		case directiveDisable:
			if dir.target == "" {
				allDisabled = true
			} else {
				disabledRules[dir.target] = true
				enabledRules[dir.target] = false
			}
		case directiveEnable:
			if dir.target == "" {
				allDisabled = false
				disabledRules = map[string]bool{}
			} else {
				disabledRules[dir.target] = false
				enabledRules[dir.target] = true
			}
		case directiveDisableNextLine:
			if dir.target == "" {
				disableNextLineLine = dir.line + 1
			} else {
				disabledRules[dir.target] = true
			}
		case directiveEnableNextLine:
			if dir.target == "" {
				allDisabled = true
			} else {
				disabledRules[dir.target] = true
			}
		}
	}
	_ = lastProcessed
	if disableNextLineLine == line {
		return true
	}
	if allDisabled {
		return true
	}
	return disabledRules[rule]
}

// isReviveDirectiveComment reports whether the given comment text is a revive
// directive comment. Such comments are removed from the documentation comments
// of the declarations.
func isReviveDirectiveComment(text string) bool {
	if !strings.HasPrefix(text, "//revive:") {
		return false
	}
	return true
}

// parseDirectives collects all the revive comment directives of the file.
func parseDirectives(f *ast.File) *directives {
	d := &directives{}
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			action, target, ok := parseDirectiveComment(c.Text)
			if !ok {
				continue
			}
			d.list = append(d.list, directive{
				line:   f.Pos() - f.Pos() + c.Pos(), // replaced below
				action: action,
				target: target,
			})
		}
	}
	return d
}
GOEOF
echo ok"}

