package lint

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"go/build"
)

// Linter is the revive linter.
type Linter struct {
	// MaxOpenFiles is the maximum number of files that are opened at the same
	// time. When it is not positive there is no limit.
	MaxOpenFiles int
	// goroot is used to resolve the packages that are not local.
	goroot string
}

// getPkgInfo resolves the given package patterns into build packages.
func (l *Linter) getPkgInfo(pkgs []string, excludes []string) ([]*build.Package, error) {
	result := []*build.Package{}
	for _, pkg := range pkgs {
		if strings.HasSuffix(pkg, "/...") || pkg == "..." {
			root := strings.TrimSuffix(pkg, "/...")
			if root == "" {
				continue
			}
			err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
				if err != nil {
					return nil
				}
				if !info.IsDir() {
					return nil
				}
				name := info.Name()
				if strings.HasPrefix(name, "_") || strings.HasPrefix(name, ".") || name == "testdata" {
					return filepath.SkipDir
				}
				if isExcluded(path, excludes) {
					return filepath.SkipDir
				}
