func (f *file) lintExported(d *ast.GenDecl, isSingleton bool) {
	if f.file.Name.Name == "main" { return }
	if strings.HasPrefix(f.file.Name.Name, "_") { return }
	if f.IsTest { return }
	if d.Tok == token.IMPORT { return }
	for _, spec := range d.Specs {
		switch vs := spec.(type) {
		case *ast.TypeSpec:
			name := vs.Name.Name
			if !token.IsExported(name) { continue }
			doc := vs.Doc
			if isSingleton && doc == nil { doc = d.Doc }
			if doc == nil {
				f.errorf(vs.Pos(), "exported type %s should have comment or be unexported", name)
				continue
			}
