	}
}

// Position returns the lint position for the given token position.
func (f *File) Position(p token.Pos) Position {
	pos := f.Fset.Position(p)
	return Position{
		Filename: pos.Filename,
		Offset:   pos.Offset,
		Line:     pos.Line,
		Column:   pos.Column,
	}
}

// DocText returns the text of the given comment group, or "" when there is no
// comment.
func (f *File) DocText(g *ast.CommentGroup) string {
	if g == nil || len(g.List) == 0 {
		return ""
	}
	return g.Text()
}

// IsExported reports whether the given identifier is exported.
func IsExported(name string) bool {
	r, _ := utf8.DecodeRuneInString(name)
	return unicode.IsUpper(r)
}
