{"command": "cd /workspace && cat > internal/rules/exported.go <<'GOEOF'
package rules

import (
	"fmt"
	"go/ast"
	"go/token"
	"strings"

	"revive/internal/lint"
)

// exportedRule checks that exported symbols have a doc comment of the right
// form.
type exportedRule struct{}

func (*exportedRule) Name() string { return "exported" }

func (*exportedRule) Category() string { return "comments" }

func (*exportedRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}

	if file.PackageName == "main" {
		return failures
	}
	if strings.HasPrefix(file.PackageName, "_") {
		return failures
	}

	for _, decl := range file.AST.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			if d.Tok == token.IMPORT {
				continue
			}
			isSingleton := len(d.Specs) == 1
			for _, spec := range d.Specs {
				switch vs := spec.(type) {
				case *ast.TypeSpec:
					failures = append(failures, checkExportedType(file, vs, d, isSingleton)...)
				case *ast.ValueSpec:
					failures = append(failures, checkExportedValue(file, vs, d, isSingleton)...)
				}
			}
		case *ast.FuncDecl:
			failures = append(failures, checkExportedFunc(file, d)...)
		}
	}
	return failures
