func (f *file) lintNames(node ast.Node) {
	ast.Inspect(node, func(node ast.Node) {
		switch node := node.(type) {
		case *ast.FuncDecl:
			f.checkName(node.Name.Name, "func")
		case *ast.Field:
			for _, name := range node.Names {
				f.checkName(name.Name, "struct field "+f.nodeString(node.Type))
			}
		case *ast.TypeSpec:
			f.checkName(node.Name.Name, "type")
		case *ast.AssignStmt:
			for _, name := range node.Lhs {
				if ident, ok := name.(*ast.Ident); ok {
					f.checkName(ident.Name, "var")
				}
			}
		case *ast.GenDecl:
			if node.Tok == token.VAR || node.Tok == token.CONST {
				for _, spec := range node.Specs {
					valueSpec := spec.(*ast.ValueSpec)
					for _, name := range valueSpec.Names {
						f.checkName(name.Name, strings.ToLower(node.Tok.String()))
					}
				}
			}
		case *ast.FuncType:
			for _, field := range node.Params.List {
				for _, name := range field.Names {
					f.checkName(name.Name, "func parameter")
				}
			}
		case *ast.File:
			if node.Name == nil { break }
			// Check the package name
			if strings.Contains(node.Name.Name, "_") {
				f.errorf(node.Name.Pos(), "don't use an underscore in package name")
				break
			}
			// ...
			if !f.IsTest {
				// golint: the package name should be lowercase
				if strings.ToUpper(node.Name.Name) != node.Name.Name { ... }
			}
		}
	})
}
