{"command": "cd /workspace && cat > internal/rules/naming.go <<'GOEOF'
package rules

import (
	"fmt"
	"go/ast"
	"strings"
	"sync"
	"unicode"

	"revive/internal/lint"
)

// stdPackages holds the names of the packages of the Go standard library.
var (
	stdPackages     = map[string]bool{}
	stdPackagesOnce sync.Once
)

// StdPackages returns the names of the standard library packages. The packages
// are loaded by the var-naming rule when it is configured.
func StdPackages() map[string]bool {
	stdPackagesOnce.Do(func() {})
	return stdPackages
}

// SetStdPackages sets the standard library package names.
func SetStdPackages(names map[string]bool) {
	stdPackages = names
	stdPackagesOnce.Do(func() {})
}

// varNamingRule checks the naming of the identifiers of a file.
type varNamingRule struct{}

func (*varNamingRule) Name() string { return "var-naming" }

func (*varNamingRule) Category() string { return "naming" }

func (r *varNamingRule) Apply(file *lint.File, arguments lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}

