type unusedParameterRule struct{}

func (*unusedParameterRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if file.IsTest { return []lint.Failure{} }
	failures := []lint.Failure{}
	walker := &unusedParameterLinter{file: file, onFailure: func(failure lint.Failure) { failures = append(failures, failure) }}
	ast.Walk(walker, file.AST)
	return failures
}

type unusedParameterLinter struct {
	file      *lint.File
	onFailure func(lint.Failure)
}

func (w *unusedParameterLinter) Visit(node ast.Node) ast.Visitor {
	switch node := node.(type) {
