type unusedParameterRule struct{}

// Apply applies the rule to the given file.
func (*unusedParameterRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if file.IsTest {
		return []lint.Failure{}
	}

	failures := []lint.Failure{}

	walker := lintSkipComments{
		v: &unusedParamVisitor{
			onFailure: func(failure lint.Failure) {
				failures = append(failures, failure)
			},
		},
	}

	ast.Walk(walker, file.AST)

	return failures
}

type unusedParamVisitor struct {
	onFailure func(lint.Failure)
}

func (v *unusedParamVisitor) Visit(node ast.Node) ast.Visitor {
	switch node := node.(type) {
	case *ast.FuncDecl:
		v.checkUnusedParams(node.Type.Params, node.Body)
	case *ast.FuncLit:
		v.checkUnusedParams(node.Type.Params, node.Body)
	}
	return v
}

func (v *unusedParamVisitor) checkUnusedParams(params *ast.FieldList, body *ast.BlockStmt) {
	if params == nil || body == nil {
		return
	}
	// revive: collect the identifiers used in the body
	used := map[string]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		if id, ok := n.(*ast.Ident); ok {
			used[id.Name] = true
		}
		return true
	})
	for _, p := range params.List {
		for _, name := range p.Names {
			if name.Name == "_" { continue }
			if !used[name.Name] {
				v.onFailure(...)
			}
		}
	}
}
```
