// blankImportsRule checks the blank imports.
type blankImportsRule struct{}

func (*blankImportsRule) Name() string { return "blank-imports" }

func (*blankImportsRule) Category() string { return "imports" }

func (*blankImportsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	if file.PackageName == "main" {
		return failures
	}
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			if is.Name == nil || is.Name.Name != "_" {
				continue
			}
			if file.DocText(is.Doc) != "" || file.DocText(is.Comment) != "" {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    "a blank import should be only in a main or test package, or have a comment justifying it",
				Position:   file.NodePosition(is),
				Confidence: 1,
			})
		}
	}
	return failures
}

// dotImportsRule checks the dot imports.
type dotImportsRule struct{}

func (*dotImportsRule) Name() string { return "dot-imports" }

func (*dotImportsRule) Category() string { return "imports" }

func (*dotImportsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	for _, decl := range file.AST.Decls {
