		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			if is.Name == nil || is.Name.Name != "." {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    "should not use dot imports",
				Position:   file.NodePosition(is),
				Confidence: 1,
			})
		}
	}
	return failures
}

// contextAsArgumentRule checks that the context is the first parameter.
type contextAsArgumentRule struct{}

func (*contextAsArgumentRule) Name() string { return "context-as-argument" }

func (*contextAsArgumentRule) Category() string { return "arg-order" }

func (*contextAsArgumentRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			if node.Recv != nil {
				return true
			}
			failures = append(failures, checkContextParams(file, node.Type.Params)...)
		case *ast.FuncLit:
			failures = append(failures, checkContextParams(file, node.Type.Params)...)
		}
		return true
	})
	return failures
}

func isContextType(file *lint.File, e ast.Expr) bool {
	if e == nil {
		return false
	}
	// revive resolves the type using the type information when it is available.
	if t := file.TypeOf(e); t != nil {
		return fmt.Sprintf("%s", t) == "context.Context"
	}
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	return sel.Sel.Name == "Context" && isContextPackage(file, sel.X)
}

func isContextPackage(file *lint.File, e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	if !ok {
		return false
	}
	// revive checks the imports of the file.
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			path := ""
			if is.Path != nil {
				path, _ = strconvUnquote(is.Path.Value)
			}
			if path != "context" {
				continue
			}
			name := "context"
			if is.Name != nil {
				name = is.Name.Name
			}
			if name == id.Name {
				return true
			}
		}
	}
	return false
}

func strconvUnquote(s string) (string, bool) {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return s[1 : len(s)-1], true
	}
	if len(s) >= 3 && s[0] == '`' && s[len(s)-1] == '`' {
		return s[1 : len(s)-1], true
	}
	return s, false
}

func checkContextParams(file *lint.File, params *ast.FieldList) []lint.Failure {
	failures := []lint.Failure{}
	if params == nil {
		return failures
	}
	found := false
	for _, field := range params.List {
		if isContextType(file, field.Type) {
			if found {
				continue
			}
			found = true
			continue
		}
		if found {
			failures = append(failures, lint.Failure{
				Failure:    "context.Context should be the first parameter of a function",
				Position:   file.NodePosition(firstContextField(params)),
				Confidence: 0.9,
			})
			return failures
		}
	}
	return failures
}

func firstContextField(params *ast.FieldList) ast.Node {
	for _, field := range params.List {
		if isContextType(nil, field.Type) {
			return field
		}
	}
	return params
}
