package rules

import (
	"fmt"
	"go/ast"
	"go/token"
	"strings"

	"revive/internal/lint"
)

// indentErrorFlowRule checks for if blocks that end with a return statement.
type indentErrorFlowRule struct{}

func (*indentErrorFlowRule) Name() string { return "indent-error-flow" }

func (*indentErrorFlowRule) Category() string { return "" }

func (*indentErrorFlowRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if ifStmt.Else == nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if len(ifStmt.Body.List) == 0 {
			return true
		}
		if _, ok := ifStmt.Body.List[len(ifStmt.Body.List)-1].(*ast.ReturnStmt); !ok {
			return true
		}
		message := "if block ends with a return statement, so drop this else and outdent its block"
		if hasShortVarDecl(ifStmt.Init) {
			message += " (move short variable declaration to its own line if necessary)"
		}
		failures = append(failures, lint.Failure{
			Failure:    message,
			Position:   file.NodePosition(elseBlock),
			Confidence: 1,
		})
		return true
	})
	return failures
}

func hasShortVarDecl(n ast.Node) bool {
	assign, ok := n.(*ast.AssignStmt)
	if !ok {
		return false
	}
	return assign.Tok == token.DEFINE && len(assign.Lhs) > 0
}

// emptyBlockRule checks for empty blocks.
type emptyBlockRule struct{}

func (*emptyBlockRule) Name() string { return "empty-block" }

func (*emptyBlockRule) Category() string { return "logic" }

func (*emptyBlockRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		var block *ast.BlockStmt
		switch node := n.(type) {
		case *ast.FuncDecl:
			if node.Body != nil && len(node.Body.List) == 0 {
				block = node.Body
			}
		case *ast.IfStmt:
			if node.Else != nil {
				if elseBlock, ok := node.Else.(*ast.BlockStmt); ok && len(elseBlock.List) == 0 {
					block = elseBlock
				}
			}
		case *ast.ForStmt:
			if node.Body != nil && len(node.Body.List) == 0 {
				block = node.Body
			}
		case *ast.RangeStmt:
			if node.Body != nil && len(node.Body.List) == 0 {
				block = node.Body
			}
		case *ast.BlockStmt:
			// revive skips the function bodies and the else blocks, they are
			// handled above.
			return true
		}
		if block == nil {
			return true
		}
		failures = append(failures, lint.Failure{
			Failure:    "this block is empty, you can remove it",
			Position:   file.NodePosition(block),
			Confidence: 1,
		})
		return true
	})
	return failures
}

// errorReturnRule checks that the error is the last return value.
type errorReturnRule struct{}

func (*errorReturnRule) Name() string { return "error-return" }

func (*errorReturnRule) Category() string { return "style" }

func (*errorReturnRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		fd, ok := n.(*ast.FuncDecl)
		if !ok || fd.Type.Results == nil || len(fd.Type.Results.List) < 2 {
			return true
		}
		results := fd.Type.Results.List
		for _, result := range results[:len(results)-1] {
			if isErrorType(file, result.Type) {
				failures = append(failures, lint.Failure{
					Failure:    "error should be the last type when returning multiple items",
					Position:   file.NodePosition(fd),
					Confidence: 0.9,
				})
				return true
			}
		}
		return true
	})
	return failures
}

func isErrorType(file *lint.File, e ast.Expr) bool {
	if id, ok := e.(*ast.Ident); ok {
		return id.Name == "error"
	}
	return false
}

// errorStringsRule checks the error strings.
type errorStringsRule struct{}

func (*errorStringsRule) Name() string { return "error-strings" }

func (*errorStringsRule) Category() string { return "errors" }

func (*errorStringsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isErrorsNew(file, call.Fun) {
			return true
		}
		if len(call.Args) != 1 {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok {
			return true
		}
		if lit.Kind.String() != "STRING" {
			return true
		}
		value, _ := strconvUnquote(lit.Value)
		if value == "" {
			return true
		}
		if !startsWithLower(value) || endsWithPunctuation(value) {
			failures = append(failures, lint.Failure{
				Failure:    "error strings should not be capitalized or end with punctuation or a newline",
				Position:   file.NodePosition(call),
				Confidence: 0.8,
			})
		}
		return true
	})
	return failures
}

func isErrorsNew(file *lint.File, e ast.Expr) bool {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	if sel.Sel.Name != "New" {
		return false
	}
	return isErrorsPackage(file, sel.X)
}

func isErrorsPackage(file *lint.File, e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	if !ok {
		return false
	}
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			path, _ := strconvUnquote(is.Path.Value)
			if path != "errors" {
				continue
			}
			name := "errors"
			if is.Name != nil {
				name = is.Name.Name
			}
			if name == id.Name {
				return true
			}
		}
	}
	return false
}

func startsWithLower(s string) bool {
	r := rune(s[0])
	return r < 'A' || r > 'Z'
}

func endsWithPunctuation(s string) bool {
	last := s[len(s)-1]
	switch last {
	case '.', ':', '!', '\n', '\t':
		return true
	}
	return false
}

// errorfRule checks for errors.New(fmt.Sprintf(...)).
type errorfRule struct{}

func (*errorfRule) Name() string { return "errorf" }

func (*errorfRule) Category() string { return "errors" }

func (*errorfRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isErrorsNew(file, call.Fun) || len(call.Args) != 1 {
			return true
		}
		inner, ok := call.Args[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isFmtSprintf(file, inner.Fun) {
			return true
		}
		failures = append(failures, lint.Failure{
			Failure:    "should replace errors.New(fmt.Sprintf(...)) with fmt.Errorf(...)",
			Position:   file.NodePosition(call),
			Confidence: 1,
			ReplacementLine: replacementLineFor(file, call, "fmt.Errorf"),
		})
		return true
	})
	return failures
}

func isFmtSprintf(file *lint.File, e ast.Expr) bool {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	if sel.Sel.Name != "Sprintf" {
		return false
	}
	return isFmtPackage(file, sel.X)
}

func isFmtPackage(file *lint.File, e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	if !ok {
		return false
	}
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			path, _ := strconvUnquote(is.Path.Value)
			if path != "fmt" {
				continue
			}
			name := "fmt"
			if is.Name != nil {
				name = is.Name.Name
			}
			if name == id.Name {
				return true
			}
		}
	}
	return false
}

// replacementLineFor builds the replacement line for the given call expression.
func replacementLineFor(file *lint.File, call *ast.CallExpr, replacement string) string {
	start := file.Fset.Position(call.Pos())
	end := file.Fset.Position(call.End())
	content := file.Content
	if start.Offset < 0 || end.Offset > len(content) || start.Offset >= end.Offset {
		return ""
	}
	line := content[start.Offset:end.Offset]
	line = strings.Replace(string(line), "errors.New(", replacement+"(", 1)
	// keep the leading indentation of the statement
	lineStart := start.Offset
	for lineStart > 0 && content[lineStart-1] != '\n' {
		lineStart--
	}
	return string(content[lineStart:start.Offset]) + string(line)
}

// incrementDecrementRule checks for x += 1 and x -= 1.
type incrementDecrementRule struct{}

func (*incrementDecrementRule) Name() string { return "increment-decrement" }

func (*incrementDecrementRule) Category() string { return "unary-op" }

func (*incrementDecrementRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		assign, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
			return true
		}
		lhs, ok := assign.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		lit, ok := assign.Rhs[0].(*ast.BasicLit)
		if !ok || lit.Kind.String() != "INT" || lit.Value != "1" {
			return true
		}
		switch assign.Tok {
		case token.ADD_ASSIGN:
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("should replace %s += 1 with %s++", lhs.Name, lhs.Name),
				Position:   file.NodePosition(assign),
				Confidence: 0.8,
			})
		case token.SUB_ASSIGN:
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("should replace %s -= 1 with %s--", lhs.Name, lhs.Name),
				Position:   file.NodePosition(assign),
				Confidence: 0.8,
			})
		}
		return true
	})
	return failures
}

// varDeclarationRule checks for var declarations that can be simplified.
type varDeclarationRule struct{}

func (*varDeclarationRule) Name() string { return "var-declaration" }

func (*varDeclarationRule) Category() string { return "type-inference" }

func (*varDeclarationRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		gen, ok := n.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "var" {
			return true
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || len(vs.Values) != 1 {
				continue
			}
			if vs.Type == nil {
				continue
			}
			value := vs.Values[0]
			switch v := value.(type) {
			case *ast.BasicLit:
				if v.Kind.String() == "INT" && v.Value == "0" {
					failures = append(failures, lint.Failure{
						Failure:    fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", v.Value, vs.Names[0].Name),
						Position:   file.NodePosition(vs),
						Confidence: 0.8,
					})
					continue
				}
				if v.Kind.String() == "STRING" && v.Value == `""` {
					failures = append(failures, lint.Failure{
						Failure:    fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", v.Value, vs.Names[0].Name),
						Position:   file.NodePosition(vs),
						Confidence: 0.8,
					})
					continue
				}
			}
			// revive checks whether the type can be inferred from the value.
			if canOmitType(file, vs.Type, value) {
				failures = append(failures, lint.Failure{
					Failure:    fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typeString(file, vs.Type), vs.Names[0].Name),
					Position:   file.NodePosition(vs),
					Confidence: 0.8,
				})
			}
		}
		return true
	})
	return failures
}

func typeString(file *lint.File, e ast.Expr) string {
	if t := file.TypeOf(e); t != nil {
		return t.String()
	}
	if id, ok := e.(*ast.Ident); ok {
		return id.Name
	}
	return ""
}

func canOmitType(file *lint.File, typ ast.Expr, value ast.Expr) bool {
	switch t := typ.(type) {
	case *ast.Ident:
		switch t.Name {
		case "int", "string", "float64", "bool":
			return matchesLiteralType(t.Name, value)
		}
	}
	return false
}

func matchesLiteralType(typ string, value ast.Expr) bool {
	lit, ok := value.(*ast.BasicLit)
	if !ok {
		return false
	}
	switch lit.Kind.String() {
	case "INT":
		return typ == "int"
	case "STRING":
		return typ == "string"
	case "FLOAT":
		return typ == "float64"
	}
	return false
}

// redefinesBuiltinIdRule checks for redefinitions of the built-in identifiers.
type redefinesBuiltinIdRule struct{}

func (*redefinesBuiltinIdRule) Name() string { return "redefines-builtin-id" }

func (*redefinesBuiltinIdRule) Category() string { return "logic" }

var builtinIdents = map[string]bool{
	"append": true, "cap": true, "close": true, "complex": true, "copy": true,
	"delete": true, "imag": true, "len": true, "make": true, "new": true,
	"panic": true, "print": true, "println": true, "real": true, "recover": true,
	"min": true, "max": true, "clear": true,
}

func (*redefinesBuiltinIdRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			if node.Recv == nil {
				failures = append(failures, checkBuiltin(file, node.Name)...)
			}
		case *ast.GenDecl:
			for _, spec := range node.Specs {
				switch s := spec.(type) {
				case *ast.ValueSpec:
					for _, name := range s.Names {
						failures = append(failures, checkBuiltin(file, name)...)
					}
				case *ast.TypeSpec:
					failures = append(failures, checkBuiltin(file, s.Name)...)
				}
			}
		case *ast.FuncType:
			if node.Params != nil {
				for _, field := range node.Params.List {
					for _, name := range field.Names {
						failures = append(failures, checkBuiltin(file, name)...)
					}
				}
			}
			if node.Results != nil {
				for _, field := range node.Results.List {
					for _, name := range field.Names {
						failures = append(failures, checkBuiltin(file, name)...)
					}
				}
			}
		case *ast.Field:
			for _, name := range node.Names {
				failures = append(failures, checkBuiltin(file, name)...)
			}
		case *ast.LabeledStmt:
			failures = append(failures, checkBuiltin(file, node.Label)...)
		}
		return true
	})
	return failures
}

func checkBuiltin(file *lint.File, ident *ast.Ident) []lint.Failure {
	if !builtinIdents[ident.Name] {
		return nil
	}
	return []lint.Failure{{
		Failure:    fmt.Sprintf("redefinition of the built-in function %s", ident.Name),
		Position:   file.NodePosition(ident),
		Confidence: 1,
	}}
}

// unreachableCodeRule checks for unreachable code.
type unreachableCodeRule struct{}

func (*unreachableCodeRule) Name() string { return "unreachable-code" }

func (*unreachableCodeRule) Category() string { return "logic" }

func (*unreachableCodeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		var list []ast.Stmt
		switch node := n.(type) {
		case *ast.BlockStmt:
			list = node.List
		case *ast.CaseClause:
			list = node.Body
		case *ast.CommClause:
			list = node.Body
		default:
			return true
		}
		for i, stmt := range list {
			if !isTerminating(file, stmt) {
				continue
			}
			if i == len(list)-1 {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    "unreachable code after this statement",
				Position:   file.NodePosition(stmt),
				Confidence: 1,
			})
		}
		return true
	})
	return failures
}

func isTerminating(file *lint.File, stmt ast.Stmt) bool {
	switch s := stmt.(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.BranchStmt:
		return s.Tok == token.BREAK || s.Tok == token.CONTINUE || s.Tok == token.GOTO
	case *ast.GoStmt:
		return false
	case *ast.DeferStmt:
		return false
	case *ast.ExprStmt:
		if call, ok := s.X.(*ast.CallExpr); ok {
			return isTerminatingCall(file, call)
		}
		return false
	case *ast.IfStmt:
		return terminatesBranch(file, s.Body) && (s.Else == nil || terminatesElse(file, s.Else))
	case *ast.ForStmt:
		if s.Cond != nil {
			return false
		}
		return s.Body == nil || terminatesBranch(file, s.Body) || hasBranchingBreak(file, s.Body)
	case *ast.SwitchStmt:
		if s.Body == nil {
			return false
		}
		for _, clause := range s.Body.List {
			cc, ok := clause.(*ast.CaseClause)
			if !ok {
				continue
			}
			if cc.List == nil {
				return terminatesBranch(file, cc) || endsWithBranch(file, cc)
			}
		}
		return false
	case *ast.BlockStmt:
		return terminatesBranch(file, s)
	}
	return false
}

func terminatesElse(file *lint.File, e ast.Stmt) bool {
	if block, ok := e.(*ast.BlockStmt); ok {
		return terminatesBranch(file, block)
	}
	return isTerminating(file, e)
}

func terminatesBranch(file *lint.File, block *ast.BlockStmt) bool {
	if block == nil || len(block.List) == 0 {
		return false
	}
	return isTerminating(file, block.List[len(block.List)-1])
}

func endsWithBranch(file *lint.File, block *ast.BlockStmt) bool {
	if block == nil || len(block.List) == 0 {
		return false
	}
	last := block.List[len(block.List)-1]
	br, ok := last.(*ast.BranchStmt)
	return ok && br.Tok == token.BREAK
}

func hasBranchingBreak(file *lint.File, block *ast.BlockStmt) bool {
	if block == nil {
		return false
	}
	found := false
	ast.Inspect(block, func(n ast.Node) bool {
		if br, ok := n.(*ast.BranchStmt); ok && br.Tok == token.BREAK {
			found = true
		}
		return true
	})
	return found
}

var terminatingCalls = map[string]bool{
	"os.Exit": true, "panic": true, "log.Fatal": true, "log.Fatalf": true,
	"log.Panic": true, "log.Panicf": true, "log.Fatalln": true, "log.Panicln": true,
	"runtime.Goexit": true, "syscall.Exit": true,
}

func isTerminatingCall(file *lint.File, call *ast.CallExpr) bool {
	name := exprName(file, call.Fun)
	return terminatingCalls[name]
}

func exprName(file *lint.File, e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return exprName(file, t.X) + "." + t.Sel.Name
	}
	return ""
}

// rangeRule checks for range statements with an unused second value.
type rangeRule struct{}

func (*rangeRule) Name() string { return "range" }

func (*rangeRule) Category() string { return "" }

func (*rangeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		rangeStmt, ok := n.(*ast.RangeStmt)
		if !ok {
			return true
		}
		if rangeStmt.Value == nil {
			return true
		}
		value, ok := rangeStmt.Value.(*ast.Ident)
		if !ok || value.Name != "_" {
			return true
		}
		key, ok := rangeStmt.Key.(*ast.Ident)
		if !ok {
			return true
		}
		message := fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s %s range ...`", key.Name, rangeStmt.Tok.String())
		failures = append(failures, lint.Failure{
			Failure:         message,
			Position:        file.NodePosition(value),
			Confidence:      1,
			ReplacementLine: rangeReplacementLine(file, rangeStmt),
		})
		return true
	})
	return failures
}

func rangeReplacementLine(file *lint.File, rangeStmt *ast.RangeStmt) string {
	start := file.Fset.Position(rangeStmt.For)
	end := file.Fset.Position(rangeStmt.Body.Lbrace)
	content := file.Content
	if start.Offset < 0 || end.Offset > len(content) || start.Offset >= end.Offset {
		return ""
	}
	text := string(content[start.Offset:end.Offset])
	text = strings.TrimRight(text, " \t\n")
	parts := strings.SplitN(text, " ", 4)
	if len(parts) < 4 {
		return ""
	}
	return parts[0] + " " + parts[1] + " " + rangeStmt.Tok.String() + " range " + exprString(file, rangeStmt.X)
}
