{"command": "cd /workspace && cat > internal/rules/params.go <<'GOEOF'
package rules

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strings"

	"revive/internal/lint"
)

// unusedParameterRule checks for unused function parameters.
type unusedParameterRule struct{}

func (*unusedParameterRule) Name() string { return "unused-parameter" }

func (*unusedParameterRule) Category() string { return "bad practice" }

func (*unusedParameterRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		case *ast.FuncLit:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		}
		return true
	})
	return failures
}

// checkUnusedParams reports the parameters of the given function that are not
// used in its body. revive walks the body scope by scope, skipping the
// identifiers that are shadowed by a declaration in a nested scope, and it also
// ignores the parameters that are redeclared with ":=" in the body.
func checkUnusedParams(file *lint.File, params *ast.FieldList, body *ast.BlockStmt) []lint.Failure {
	failures := []lint.Failure{}
	if params == nil || body == nil {
		return failures
	}
	toReport := map[string]bool{}
	paramIdents := map[string]*ast.Ident{}
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			toReport[name.Name] = true
			paramIdents[name.Name] = name
		}
	}
	// revive: revive removes the parameters that are redeclared with ":=" in the
	// body of the function.
	for _, stmt := range body.List {
		assign, ok := stmt.(*ast.AssignStmt)
		if !ok || assign.Tok != token.DEFINE {
			continue
		}
		for _, lhs := range assign.Lhs {
			if id, ok := lhs.(*ast.Ident); ok {
				delete(toReport, id.Name)
			}
		}
	}
	// revive: revive collects the identifiers that are used in the body, taking
	// into account the shadowing of the parameters in the nested scopes.
	used := map[string]bool{}
	walkBody(file, body, paramIdents, used)
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			if !toReport[name.Name] {
				continue
			}
			if used[name.Name] {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
				Position:   file.NodePosition(name),
				Confidence: 1,
			})
		}
	}
	return failures
}

// walkBody walks the statements of the given block, collecting the identifiers
// that refer to the given parameters. The declarations of the given block do not
// shadow the parameters, but the declarations of the nested scopes do.
func walkBody(file *lint.File, block *ast.BlockStmt, params map[string]*ast.Ident, used map[string]bool) {
	if block == nil {
		return
	}
	shadowed := map[string]bool{}
	for _, stmt := range block.List {
		collectUses(file, stmt, params, shadowed, used)
	}
}

// collectUses walks the given statement and collects the identifiers that refer
// to the parameters of the function.
func collectUses(file *lint.File, n ast.Node, params map[string]*ast.Ident, shadowed map[string]bool, used map[string]bool) {
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.Ident:
			if shadowed[node.Name] {
				return true
			}
			if obj, ok := file.TypeInfo.Uses[node]; ok {
				if obj != nil && isParamObject(obj, params) {
					used[node.Name] = true
					return true
				}
				// revive resolves the identifier by name when the type
				// information is not available.
				if _, ok := params[node.Name]; ok {
					used[node.Name] = true
				}
				return true
			}
			if _, ok := params[node.Name]; ok {
				// revive: revive treats the identifier as a use of the parameter
				// when it is not a declaration.
				if _, isDef := file.TypeInfo.Defs[node]; !isDef {
					used[node.Name] = true
				}
			}
			return true
		case *ast.BlockStmt:
			// handled below
			return false
		case *ast.IfStmt:
			if node.Init != nil {
				collectWithShadowing(file, node.Init, params, shadowed, used)
			}
			if node.Cond != nil {
				collectUses(file, node.Cond, params, shadowed, used)
			}
			visitNestedBlock(file, node.Body, params, shadowed, used)
			if node.Else != nil {
				collectUses(file, node.Else, params, shadowed, used)
			}
			return false
		case *ast.ForStmt:
			if node.Init != nil {
				collectWithShadowing(file, node.Init, params, shadowed, used)
			}
			if node.Cond != nil {
				collectUses(file, node.Cond, params, shadowed, used)
			}
			if node.Post != nil {
				collectWithShadowing(file, node.Post, params, shadowed, used)
			}
			visitNestedBlock(file, node.Body, params, shadowed, used)
			return false
		case *ast.RangeStmt:
			if node.Key != nil {
				collectWithShadowing(file, node.Key, params, shadowed, used)
			}
			if node.Value != nil {
				collectWithShadowing(file, node.Value, params, shadowed, used)
			}
			if node.X != nil {
				collectUses(file, node.X, params, shadowed, used)
			}
			visitNestedBlock(file, node.Body, params, shadowed, used)
			return false
		case *ast.SwitchStmt:
			if node.Init != nil {
				collectWithShadowing(file, node.Init, params, shadowed, used)
			}
			if node.Tag != nil {
				collectUses(file, node.Tag, params, shadowed, used)
			}
			if node.Body != nil {
				visitNestedBlock(file, node.Body, params, shadowed, used)
			}
			return false
		case *ast.TypeSwitchStmt:
			if node.Init != nil {
				collectWithShadowing(file, node.Init, params, shadowed, used)
			}
			if node.Assign != nil {
				collectWithShadowing(file, node.Assign, params, shadowed, used)
			}
			if node.Body != nil {
				visitNestedBlock(file, node.Body, params, shadowed, used)
			}
			return false
		case *ast.SelectStmt:
			if node.Body != nil {
				visitNestedBlock(file, node.Body, params, shadowed, used)
			}
			return false
		case *ast.FuncLit:
			visitNestedBlock(file, node.Body, params, shadowed, used)
			return false
		case *ast.DeclStmt:
			// revive: the declarations of the current block do not shadow the
			// parameters.
			return true
		}
		return true
	})
}

// collectWithShadowing collects the uses of the identifiers of the given
// expression, marking the declared names as shadowing.
func collectWithShadowing(file *lint.File, n ast.Node, params map[string]*ast.Ident, shadowed map[string]bool, used map[string]bool) {
	// revive: revive first collects the declarations of the expression.
	var declared []*ast.Ident
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						declared = append(declared, id)
					}
				}
			}
		case *ast.ValueSpec:
			declared = append(declared, node.Names...)
		}
		return true
	})
	for _, id := range declared {
		shadowed[id.Name] = true
	}
	collectUses(file, n, params, shadowed, used)
}

// visitNestedBlock visits the given block in a new scope.
func visitNestedBlock(file *lint.File, block *ast.BlockStmt, params map[string]*ast.Ident, shadowed map[string]bool, used map[string]bool) {
	if block == nil {
		return
	}
	// revive: revive collects the declarations of the nested block.
	local := map[string]bool{}
	for _, stmt := range block.List {
		collectDeclarations(stmt, local)
	}
	// revive: revive copies the shadowing state of the enclosing scope.
	merged := map[string]bool{}
	for k := range shadowed {
		merged[k] = true
	}
	for k := range local {
		merged[k] = true
	}
	for _, stmt := range block.List {
		collectUses(file, stmt, params, merged, used)
	}
}

// collectDeclarations collects the names declared at the top level of the given
// statement.
func collectDeclarations(n ast.Node, declared map[string]bool) {
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						declared[id.Name] = true
					}
				}
				return false
			}
		case *ast.ValueSpec:
			for _, name := range node.Names {
				declared[name.Name] = true
			}
			return false
		case *ast.FuncLit:
			return false
		}
		return true
	})
}

func isParamObject(obj types.Object, params map[string]*ast.Ident) bool {
	if obj == nil {
		return false
	}
	for _, id := range params {
		if _, ok := file_ParamObject(obj, id); ok {
			return true
		}
	}
	return false
}
