cd /workspace && cat > internal/rules/params.go <<'GOEOF'
package rules

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strings"

	"revive/internal/lint"
)

// unusedParameterRule checks for unused function parameters.
type unusedParameterRule struct{}

func (*unusedParameterRule) Name() string { return "unused-parameter" }

func (*unusedParameterRule) Category() string { return "bad practice" }

func (*unusedParameterRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		case *ast.FuncLit:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		}
		return true
	})
	return failures
}

// checkUnusedParams reports the parameters of the given function that are not
// used in its body. revive walks the body scope by scope, skipping the
// identifiers that are shadowed by a declaration in a nested scope, and it also
// ignores the parameters that are redeclared with ":=" in the body.
func checkUnusedParams(file *lint.File, params *ast.FieldList, body *ast.BlockStmt) []lint.Failure {
	failures := []lint.Failure{}
	if params == nil || body == nil {
		return failures
	}
	toReport := map[string]bool{}
	paramIdents := map[string]*ast.Ident{}
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			toReport[name.Name] = true
			paramIdents[name.Name] = name
		}
	}
	// revive: revive removes the parameters that are redeclared with ":=" in the
	// body of the function.
	for _, stmt := range body.List {
		assign, ok := stmt.(*ast.AssignStmt)
		if !ok || assign.Tok != token.DEFINE {
			continue
		}
		for _, lhs := range assign.Lhs {
			if id, ok := lhs.(*ast.Ident); ok {
				delete(toReport, id.Name)
			}
		}
	}
	// revive: revive collects the identifiers that are used in the body, taking
	// into account the shadowing of the parameters in the nested scopes.
	used := map[string]bool{}
	walkBody(file, body, paramIdents, used)
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			if !toReport[name.Name] {
				continue
			}
			if used[name.Name] {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
				Position:   file.NodePosition(name),
				Confidence: 1,
			})
		}
	}
	return failures
}

// walkBody walks the statements of the given block, collecting the identifiers
// that refer to the given parameters. The declarations of the given block do not
// shadow the parameters, but the declarations of the nested scopes do.
func walkBody(file *lint.File, block *ast.BlockStmt, params map[string]*ast.Ident, used map[string]bool) {
	if block == nil {
		return
	}
	shadowed := map[string]bool{}
	for _, stmt := range block.List {
		collectUses(file, stmt, params, shadowed, used)
	}
}

// collectUses walks the given statement and collects the identifiers that refer
// to the parameters of the function.
func collectUses(file *lint.File, n ast.Node, params map[string]*ast.Ident, shadowed map[string]bool, used map[string]bool) {
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.Ident:
			if shadowed[node.Name] {
				return true
			}
			if obj, ok := file.TypeInfo.Uses[node]; ok {
				if obj != nil && isParamObject(obj, params) {
					used[node.Name] = true
					return true
				}
				// revive resolves the identifier by name when the type
				// information is not available.
				if _, ok := params[node.Name]; ok {
					used[node.Name] = true
				}
				return true
			}
			if _, ok := params[node.Name]; ok {
				// revive: revive treats the identifier as a use of the parameter
				// when it is not a declaration.
				if _, isDef := file.TypeInfo.Defs[node]; !isDef {
					used[node.Name] = true
				}
			}
			return true
		case *ast.BlockStmt:
			// handled below
			return false
		case *ast.IfStmt:
			if node.Init != nil {
				collectWithShadowing(file, node.Init, params, shadowed, used)
			}
			if node.Cond != nil {
				collectUses(file, node.Cond, params, shadowed, used)
