{"command": "cd /workspace && cat > internal/rules/params.go <<'GOEOF'
package rules

import (
	"fmt"
	"go/ast"
	"go/token"

	"revive/internal/lint"
)

// unusedParameterRule checks for unused function parameters.
type unusedParameterRule struct{}

func (*unusedParameterRule) Name() string { return "unused-parameter" }

func (*unusedParameterRule) Category() string { return "bad practice" }

func (*unusedParameterRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.FuncDecl:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		case *ast.FuncLit:
			failures = append(failures, checkUnusedParams(file, node.Type.Params, node.Body)...)
		}
		return true
	})
	return failures
}

// checkUnusedParams reports the parameters of the given function that are not
// used in its body.
//
// revive walks the body scope by scope and skips the identifiers that are
// shadowed by a declaration of an inner scope. The declarations of the body of
// the function itself do not shadow the parameters, but revive ignores the
// parameters that are redeclared with ":=" in the body of the function.
func checkUnusedParams(file *lint.File, params *ast.FieldList, body *ast.BlockStmt) []lint.Failure {
	failures := []lint.Failure{}
	if params == nil || body == nil {
		return failures
	}
	toReport := map[string]bool{}
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			toReport[name.Name] = true
		}
	}
	for _, stmt := range body.List {
		assign, ok := stmt.(*ast.AssignStmt)
		if !ok || assign.Tok != token.DEFINE {
			continue
		}
		for _, lhs := range assign.Lhs {
			if id, ok := lhs.(*ast.Ident); ok {
				delete(toReport, id.Name)
			}
		}
	}
	used := map[string]bool{}
	for _, stmt := range body.List {
		collectUses(file, stmt, toReport, map[string]bool{}, used)
	}
	for _, field := range params.List {
		for _, name := range field.Names {
			if name.Name == "_" {
				continue
			}
			if !toReport[name.Name] {
				continue
			}
			if used[name.Name] {
				continue
			}
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name.Name),
				Position:   file.NodePosition(name),
				Confidence: 1,
			})
		}
	}
	return failures
}

// collectUses walks the given node and collects the names of the identifiers
// that refer to the parameters of the function. The names of the shadowed set
// are ignored.
func collectUses(file *lint.File, n ast.Node, params map[string]bool, shadowed map[string]bool, used map[string]bool) {
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.IfStmt:
			visitScope(file, node.Init, node.Cond, node.Body, node.Else, params, shadowed, used)
			return false
		case *ast.ForStmt:
			visitScope(file, node.Init, node.Cond, node.Body, nil, params, shadowed, used)
			if node.Post != nil {
				visitScope(file, node.Post, nil, nil, nil, params, shadowed, used)
			}
			return false
		case *ast.RangeStmt:
			visitScope(file, node.X, nil, node.Body, nil, params, shadowed, used)
			return false
		case *ast.SwitchStmt:
			visitScope(file, node.Init, node.Tag, node.Body, nil, params, shadowed, used)
			return false
		case *ast.TypeSwitchStmt:
			visitScope(file, node.Init, node.Assign, node.Body, nil, params, shadowed, used)
			return false
		case *ast.SelectStmt:
			visitScope(file, nil, nil, node.Body, nil, params, shadowed, used)
			return false
		case *ast.FuncLit:
			visitScope(file, nil, nil, node.Body, nil, params, shadowed, used)
			return false
		case *ast.BlockStmt:
			visitBlock(file, node, params, shadowed, used)
			return false
		case *ast.Ident:
			if shadowed[node.Name] {
				return true
			}
			if _, ok := params[node.Name]; !ok {
				return true
			}
			if isDeclaration(file, node) {
				return true
			}
			used[node.Name] = true
			return true
		}
		return true
	})
}

// visitBlock visits the statements of the given block, tracking the declarations
// of the block.
func visitBlock(file *lint.File, block *ast.BlockStmt, params map[string]bool, shadowed map[string]bool, used map[string]bool) {
	if block == nil {
		return
	}
	local := map[string]bool{}
	for k := range shadowed {
		local[k] = true
	}
	for _, stmt := range block.List {
		// revive: revive collects the declarations of the statement first and
		// then walks the statement, so that the uses that come after a
		// declaration are considered shadowed.
		before := map[string]bool{}
		for k := range local {
			before[k] = true
		}
		declared := declaredNames(stmt)
		for _, name := range declared {
			local[name] = true
		}
		collectUses(file, stmt, params, local, used)
		_ = before
	}
}

func visitScope(file *lint.File, init ast.Node, cond ast.Node, body *ast.BlockStmt, elseStmt ast.Stmt, params map[string]bool, shadowed map[string]bool, used map[string]bool) {
	local := map[string]bool{}
	for k := range shadowed {
		local[k] = true
	}
	if init != nil {
		for _, name := range declaredNames(init) {
			local[name] = true
		}
		collectUses(file, init, params, local, used)
	}
	if cond != nil {
		collectUses(file, cond, params, local, used)
	}
	if body != nil {
		inner := map[string]bool{}
		for k := range local {
			inner[k] = true
		}
		for _, stmt := range body.List {
			for _, name := range declaredNames(stmt) {
				inner[name] = true
			}
			collectUses(file, stmt, params, inner, used)
		}
	}
	if elseStmt != nil {
		outer := map[string]bool{}
		for k := range shadowed {
			outer[k] = true
		}
		collectUses(file, elseStmt, params, outer, used)
	}
}

// declaredNames returns the names declared at the top level of the given node.
func declaredNames(n ast.Node) []string {
	var names []string
	ast.Inspect(n, func(node ast.Node) bool {
		switch node := node.(type) {
		case *ast.AssignStmt:
			if node.Tok == token.DEFINE {
				for _, lhs := range node.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						names = append(names, id.Name)
					}
				}
				return false
			}
		case *ast.ValueSpec:
			for _, name := range node.Names {
				names = append(names, name.Name)
			}
			return false
		case *ast.FuncLit:
			return false
		}
		return true
	})
	return names
}

// isDeclaration reports whether the given identifier is a declaration.
func isDeclaration(file *lint.File, ident *ast.Ident) bool {
	if file.TypeInfo == nil {
		return false
	}
	_, ok := file.TypeInfo.Defs[ident]
	return ok
}
GOEOF
/usr/local/go/bin/go build ./internal/... 2>&1|head"}

