			visitScope(file, node.Init, node.Cond, node.Body, node.Else, params, shadowed, used)
			return false
		case *ast.ForStmt:
			visitScope(file, node.Init, node.Cond, node.Body, nil, params, shadowed, used)
			if node.Post != nil {
				visitScope(file, node.Post, nil, nil, nil, params, shadowed, used)
			}
			return false
		case *ast.RangeStmt:
			visitScope(file, node.X, nil, node.Body, nil, params, shadowed, used)
			return false
		case *ast.SwitchStmt:
			visitScope(file, node.Init, node.Tag, node.Body, nil, params, shadowed, used)
			return false
		case *ast.TypeSwitchStmt:
			visitScope(file, node.Init, node.Assign, node.Body, nil, params, shadowed, used)
			return false
		case *ast.SelectStmt:
			visitScope(file, nil, nil, node.Body, nil, params, shadowed, used)
			return false
		case *ast.FuncLit:
			visitScope(file, nil, nil, node.Body, nil, params, shadowed, used)
			return false
