package rules

import (
	"fmt"
	"go/ast"
	"go/types"
	"strings"

	"revive/internal/lint"
)

// packageCommentsRule checks the package comments.
type packageCommentsRule struct{}

func (*packageCommentsRule) Name() string { return "package-comments" }

func (*packageCommentsRule) Category() string { return "comments" }

func (*packageCommentsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	doc := file.AST.Doc
	if file.DocText(doc) != "" {
		name := file.PackageName
		if !strings.HasPrefix(file.DocText(doc), "Package "+name+" ") {
			failures = append(failures, lint.Failure{
				Failure:    fmt.Sprintf("package comment should be of the form \"Package %s ...\"", name),
				Position:   file.NodePosition(doc),
				Confidence: 1,
			})
		}
		return failures
	}
	// revive reports the missing package comment only once per package.
	for _, other := range file.Package.Files {
		if other == file {
			continue
		}
		if file.DocText(other.AST.Doc) != "" {
			return failures
		}
	}
	failures = append(failures, lint.Failure{
		Failure:    "should have a package comment",
		Position:   file.NodePosition(file.AST.Name),
		Confidence: 1,
	})
	return failures
}

// receiverNamingRule checks that the receiver names are consistent.
type receiverNamingRule struct{}

func (*receiverNamingRule) Name() string { return "receiver-naming" }

func (*receiverNamingRule) Category() string { return "naming" }

func (*receiverNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	names := map[string]string{}
	for _, decl := range file.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) == 0 {
			continue
		}
		receiver := fd.Recv.List[0]
		if len(receiver.Names) == 0 {
			continue
		}
		name := receiver.Names[0].Name
		if name == "_" {
			continue
		}
		typeName := receiverTypeName(receiver.Type)
		if typeName == "" {
			continue
		}
		if previous, ok := names[typeName]; ok {
			if previous != name {
				failures = append(failures, lint.Failure{
					Failure:    fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", name, previous, typeName),
					Position:   file.NodePosition(receiver),
					Confidence: 1,
				})
			}
			continue
		}
		names[typeName] = name
	}
	return failures
}

func receiverTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			return id.Name
		}
	}
	return ""
}

// unexportedReturnRule checks for exported functions that return unexported
// types.
type unexportedReturnRule struct{}

func (*unexportedReturnRule) Name() string { return "unexported-return" }

func (*unexportedReturnRule) Category() string { return "unexported-type-in-api" }

func (*unexportedReturnRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	for _, decl := range file.AST.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv != nil || !lint.IsExported(fd.Name.Name) {
			continue
		}
		if fd.Type.Results == nil {
			continue
		}
		for _, result := range fd.Type.Results.List {
			typ := file.TypeOf(result.Type)
			if typ == nil {
				continue
			}
			name := typ.String()
			if strings.Contains(name, strings.ToLower(file.PackageName)) {
				failures = append(failures, lint.Failure{
					Failure:    fmt.Sprintf("exported func %s returns unexported type %s, which can be annoying to use", fd.Name.Name, name),
					Position:   file.NodePosition(result.Type),
					Confidence: 0.8,
				})
			}
		}
	}
	return failures
}

// errorNamingRule checks the naming of the error variables.
type errorNamingRule struct{}

func (*errorNamingRule) Name() string { return "error-naming" }

func (*errorNamingRule) Category() string { return "naming" }

func (*errorNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "var" {
			continue
		}
		for _, spec := range gen.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || len(vs.Values) == 0 {
				continue
			}
			typ := file.TypeOf(vs.Type)
			if typ == nil {
				continue
			}
			if typ.String() != "error" {
				continue
			}
			for _, name := range vs.Names {
				if name.Name == "_" {
					continue
				}
				if strings.HasPrefix(name.Name, "err") || strings.HasPrefix(name.Name, "Err") {
					continue
				}
				form := "errFoo"
				if lint.IsExported(name.Name) {
					form = "ErrFoo"
				}
				failures = append(failures, lint.Failure{
					Failure:    fmt.Sprintf("error var %s should have name of the form %s", name.Name, form),
					Position:   file.NodePosition(name),
					Confidence: 0.9,
				})
			}
		}
	}
	return failures
}

// contextKeysTypeRule checks the keys of context.WithValue calls.
type contextKeysTypeRule struct{}

func (*contextKeysTypeRule) Name() string { return "context-keys-type" }

func (*contextKeysTypeRule) Category() string { return "content" }

func (*contextKeysTypeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isContextWithValue(file, call.Fun) {
			return true
		}
		if len(call.Args) != 3 {
			return true
		}
		keyType := file.TypeOf(call.Args[1])
		if keyType == nil {
			return true
		}
		basic, ok := keyType.(*types.Basic)
		if !ok {
			return true
		}
		failures = append(failures, lint.Failure{
			Failure:    fmt.Sprintf("should not use basic type %s as key in context.WithValue", keyType.String()),
			Position:   file.NodePosition(call),
			Confidence: 1,
		})
		return true
	})
	return failures
}

func isContextWithValue(file *lint.File, e ast.Expr) bool {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	if sel.Sel.Name != "WithValue" {
		return false
	}
	return isContextImport(file, sel.X)
}

func isContextImport(file *lint.File, e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	if !ok {
		return false
	}
	for _, decl := range file.AST.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok.String() != "import" {
			continue
		}
		for _, spec := range gen.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			path, _ := strconvUnquote(is.Path.Value)
			if path != "context" {
				continue
			}
			name := "context"
			if is.Name != nil {
				name = is.Name.Name
			}
			if name == id.Name {
				return true
			}
		}
	}
	return false
}
