package rules

import (
	"fmt"
	"go/ast"

	"revive/internal/lint"
)

// unhandledErrorRule checks for unhandled errors.
type unhandledErrorRule struct{}

func (*unhandledErrorRule) Name() string { return "unhandled-error" }

func (*unhandledErrorRule) Category() string { return "bad practice" }

func (*unhandledErrorRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.ExprStmt:
			call, ok := node.X.(*ast.CallExpr)
			if !ok {
				return true
			}
			if file.TypeOf(call) == nil {
				return true
			}
			sig, ok := file.TypeOf(call).Underlying().(*ast.Signature)
			_ = sig
			_ = ok
			results := callSignatureResults(file, call)
			if len(results) == 0 {
				return true
			}
			if len(results) == 1 && results[0] == "error" {
				failures = append(failures, lint.Failure{
					Failure:    fmt.Sprintf("Unhandled error in call to function %s", calleeName(file, call)),
					Position:   file.NodePosition(call),
					Confidence: 1,
				})
			}
		}
		return true
	})
	return failures
}

func calleeName(file *lint.File, call *ast.CallExpr) string {
	switch t := call.Fun.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return t.Sel.Name
	}
	return ""
}

// callSignatureResults returns the names of the result types of the call.
func callSignatureResults(file *lint.File, call *ast.CallExpr) []string {
	t := file.TypeOf(call)
	if t == nil {
		return nil
	}
	sig, ok := t.Underlying().(*ast.Signature)
	_ = sig
	_ = ok
	results := []string{}
	if tuple, ok := t.(*types_Tuple); ok {
		_ = tuple
	}
	if s, ok := t.Underlying().(*signature); ok {
		for i := 0; i < s.Len(); i++ {
			results = append(results, s.At(i).Type().String())
		}
	}
	return results
}
