{"command": "cd /workspace && cat > internal/formatter/formatter.go <<'GOEOF'
package formatter

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"

	"revive/internal/lint"
)

const ruleBaseURL = "https://revive.run/r#"

// Formatter is the interface implemented by all the formatters.
type Formatter interface {
	Format(failures []lint.Failure, config *lint.Config, writer io.Writer) error
}

// GetFormatter returns the formatter with the given name.
func GetFormatter(name string) (Formatter, error) {
	switch name {
	case "default", "":
		return &defaultFormatter{}, nil
	case "friendly":
		return &friendlyFormatter{}, nil
	case "stylish":
		return &stylishFormatter{}, nil
	case "json":
		return &jsonFormatter{}, nil
	case "ndjson":
		return &ndjsonFormatter{}, nil
	case "checkstyle":
		return &checkstyleFormatter{}, nil
	case "sarif":
		return &sarifFormatter{}, nil
	case "plain":
		return &plainFormatter{}, nil
	case "unix":
		return &unixFormatter{}, nil
	}
	return nil, fmt.Errorf("unknown formatter %s", name)
}

// defaultFormatter prints the failures in the golint format.
type defaultFormatter struct{}

func (f *defaultFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	for _, failure := range failures {
		pos := failure.Position.Start
		fmt.Fprintf(w, "%s:%d:%d: %s\n", pos.Filename, pos.Line, pos.Column, failure.Failure)
	}
	return nil
}

// plainFormatter prints the failures with the URL of the rule.
type plainFormatter struct{}

func (f *plainFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	for _, failure := range failures {
		pos := failure.Position.Start
		fmt.Fprintf(w, "%s:%d:%d: %s %s\n", pos.Filename, pos.Line, pos.Column, failure.Failure, ruleBaseURL+failure.RuleName)
	}
	fmt.Fprint(w, "\n")
	return nil
}

// unixFormatter prints the failures in the unix format.
type unixFormatter struct{}

func (f *unixFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	for _, failure := range failures {
		pos := failure.Position.Start
		fmt.Fprintf(w, "%s:%d:%d: [%s] %s\n", pos.Filename, pos.Line, pos.Column, failure.RuleName, failure.Failure)
	}
	fmt.Fprint(w, "\n")
	return nil
}

// jsonFormatter prints the failures as JSON.
type jsonFormatter struct{}

func (f *jsonFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	data, err := json.Marshal(failures)
	if err != nil {
		return err
	}
	fmt.Fprintln(w, string(data))
	return nil
}

// ndjsonFormatter prints the failures as newline delimited JSON.
type ndjsonFormatter struct{}

func (f *ndjsonFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	for _, failure := range failures {
		data, err := json.Marshal(failure)
		if err != nil {
			return err
		}
		fmt.Fprintln(w, string(data))
	}
	fmt.Fprint(w, "\n")
	return nil
}

// checkstyleFormatter prints the failures in the checkstyle format.
type checkstyleFormatter struct{}

func (f *checkstyleFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	fmt.Fprintln(w, "<?xml version='1.0' encoding='UTF-8'?>")
	fmt.Fprintln(w, "<checkstyle version=\"5.0\">")
	files := map[string][]lint.Failure{}
	for _, failure := range failures {
		files[failure.Position.Start.Filename] = append(files[failure.Position.Start.Filename], failure)
	}
	names := []string{}
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		fmt.Fprintf(w, "    <file name=\"%s\">\n", xmlEscape(name))
		for _, failure := range files[name] {
			pos := failure.Position.Start
			fmt.Fprintf(w, "      <error line=\"%d\" column=\"%d\" message=\"%s (confidence %s)\" severity=\"%s\" source=\"revive/%s\"/>\n",
				pos.Line, pos.Column, xmlEscape(failure.Failure), confidenceString(failure.Confidence), failure.Severity, failure.RuleName)
		}
		fmt.Fprintln(w, "    </file>")
	}
	fmt.Fprintln(w, "</checkstyle>")
	return nil
}

func confidenceString(confidence float64) string {
	s := fmt.Sprintf("%g", confidence)
	return s
}

func xmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&#34;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

type sarifRule struct {
	HelpURI   string            `json:"helpUri"`
	ID        string            `json:"id"`
	Properties map[string]string `json:"properties"`
}

type sarifRegion struct {
	StartColumn int `json:"startColumn"`
	StartLine   int `json:"startLine"`
}

type sarifArtifactLocation struct {
	URI string `json:"uri"`
}

type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           sarifRegion           `json:"region"`
}

type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}

type sarifMessage struct {
	Text string `json:"text"`
}

type sarifResult struct {
	Level     string          `json:"level,omitempty"`
	Locations []sarifLocation `json:"locations"`
	Message   sarifMessage    `json:"message"`
	RuleID    string          `json:"ruleId"`
}

type sarifDriver struct {
	InformationURI string      `json:"informationUri"`
	Name           string      `json:"name"`
	Rules          []sarifRule `json:"rules,omitempty"`
}

type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}

type sarifRun struct {
	Results []sarifResult `json:"results,omitempty"`
	Tool    sarifTool     `json:"tool"`
}

type sarifOutput struct {
	Runs    []sarifRun `json:"runs"`
	Version string     `json:"version"`
}

// sarifFormatter prints the failures in the SARIF format.
type sarifFormatter struct{}

func (f *sarifFormatter) Format(failures []lint.Failure, config *lint.Config, w io.Writer) error {
	results := []sarifResult{}
	for _, failure := range failures {
		pos := failure.Position.Start
		results = append(results, sarifResult{
			Level: failure.Severity,
			Locations: []sarifLocation{{
				PhysicalLocation: sarifPhysicalLocation{
					ArtifactLocation: sarifArtifactLocation{URI: pos.Filename},
					Region: sarifRegion{
						StartColumn: pos.Column,
						StartLine:   pos.Line,
					},
				},
			}},
			Message: sarifMessage{Text: failure.Failure},
			RuleID:  failure.RuleName,
		})
	}
	// revive only emits a single rule in the tool description.
	rules := []sarifRule{}
	if len(config.Rules) > 0 {
		names := []string{}
		for name := range config.Rules {
			names = append(names, name)
		}
		sort.Strings(names)
		name := names[len(names)-1]
		rules = append(rules, sarifRule{
			HelpURI: ruleBaseURL + name,
			ID:      name,
			Properties: map[string]string{
				"severity": config.Rules[name].Severity,
			},
		})
	}
	output := sarifOutput{
		Runs: []sarifRun{{
			Results: results,
			Tool: sarifTool{
				Driver: sarifDriver{
					InformationURI: "https://revive.run",
					Name:           "revive",
					Rules:          rules,
				},
			},
		}},
		Version: "2.1.0",
	}
	data, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		return err
	}
	fmt.Fprintln(w, string(data))
	return nil
}

// friendlyFormatter prints the failures in a human friendly format.
type friendlyFormatter struct{}

func (f *friendlyFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	colors := isTerminal(w)
	var (
		red    = func(s string) string { return s }
		yellow = func(s string) string { return s }
		green  = func(s string) string { return s }
	)
	if colors {
		red = func(s string) string { return "\033[31m" + s + "\033[0m" }
		yellow = func(s string) string { return "\033[33m" + s + "\033[0m" }
		green = func(s string) string { return "\033[32m" + s + "\033[0m" }
	}
	errorCount := 0
	warningCount := 0
	errorRules := map[string]int{}
	warningRules := map[string]int{}
