			Properties: map[string]string{
				"severity": config.Rules[name].Severity,
			},
		})
	}
	output := sarifOutput{
		Runs: []sarifRun{{
			Results: results,
			Tool: sarifTool{
				Driver: sarifDriver{
					InformationURI: "https://revive.run",
					Name:           "revive",
					Rules:          rules,
				},
			},
		}},
		Version: "2.1.0",
	}
	data, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		return err
	}
	fmt.Fprintln(w, string(data))
	return nil
}

// friendlyFormatter prints the failures in a human friendly format.
type friendlyFormatter struct{}

func (f *friendlyFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	colors := isTerminal(w)
	var (
		red    = func(s string) string { return s }
		yellow = func(s string) string { return s }
		green  = func(s string) string { return s }
	)
	if colors {
		red = func(s string) string { return "\033[31m" + s + "\033[0m" }
		yellow = func(s string) string { return "\033[33m" + s + "\033[0m" }
		green = func(s string) string { return "\033[32m" + s + "\033[0m" }
	}
	errorCount := 0
	warningCount := 0
	errorRules := map[string]int{}
	warningRules := map[string]int{}
	for _, failure := range failures {
		var (
			symbol string
			color  func(string) string
		)
		if failure.Severity == lint.SeverityError {
			symbol = red("✘")
			color = red
			errorCount++
			errorRules[failure.RuleName]++
		} else {
			symbol = yellow("⚠")
			color = yellow
			warningCount++
			warningRules[failure.RuleName]++
		}
		pos := failure.Position.Start
		fmt.Fprintf(w, "  %s  %s  %s\n", symbol, ruleBaseURL+failure.RuleName, green(failure.Failure))
		fmt.Fprintf(w, "  %s:%d:%d\n", pos.Filename, pos.Line, pos.Column)
		fmt.Fprint(w, "\n")
	}
	if len(failures) == 0 {
		return nil
	}
	summary := fmt.Sprintf("%d problem", len(failures))
	if len(failures) > 1 {
		summary = fmt.Sprintf("%d problems", len(failures))
	}
	summary += fmt.Sprintf(" (%d errors, %d warnings)", errorCount, warningCount)
	fmt.Fprintf(w, "%s %s\n", color(symbolFor(errorCount)), color(summary))
	fmt.Fprint(w, "\n")
	if errorCount > 0 {
		fmt.Fprintf(w, "%s\n", color("Errors:"))
		printRuleCounts(w, errorRules)
		fmt.Fprint(w, "\n")
	}
	if warningCount > 0 {
		fmt.Fprintf(w, "%s\n", color("Warnings:"))
		printRuleCounts(w, warningRules)
		fmt.Fprint(w, "\n")
	}
	fmt.Fprint(w, "\n")
	return nil
}

func symbolFor(errors int) string {
	if errors > 0 {
		return "✘"
	}
	return "⚠"
}

func printRuleCounts(w io.Writer, counts map[string]int) {
	names := []string{}
	for name := range counts {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		fmt.Fprintf(w, "  %d  %s\n", counts[name], name)
	}
}

// isTerminal reports whether the given writer is a terminal.
func isTerminal(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return isTerminalFile(f.Fd())
}

// stylishFormatter prints the failures in a tabular format.
type stylishFormatter struct{}

func (f *stylishFormatter) Format(failures []lint.Failure, _ *lint.Config, w io.Writer) error {
	files := map[string][]lint.Failure{}
	for _, failure := range failures {
		files[failure.Position.Start.Filename] = append(files[failure.Position.Start.Filename], failure)
	}
	names := []string{}
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	errorCount := 0
	warningCount := 0
	for _, name := range names {
		list := files[name]
		fmt.Fprintf(w, "%s\n", name)
		// revive computes the width of the position column.
		posWidth := 0
		urlWidth := 0
		for _, failure := range list {
			pos := failure.Position.Start
			p := fmt.Sprintf("(%d, %d)", pos.Line, pos.Column)
			if len(p) > posWidth {
				posWidth = len(p)
			}
			u := ruleBaseURL + failure.RuleName
			if len(u) > urlWidth {
				urlWidth = len(u)
			}
		}
		for _, failure := range list {
			pos := failure.Position.Start
			p := fmt.Sprintf("(%d, %d)", pos.Line, pos.Column)
			fmt.Fprintf(w, "  %-*s  %-*s  %s\n", posWidth, p, urlWidth, ruleBaseURL+failure.RuleName, failure.Failure)
			if failure.Severity == lint.SeverityError {
				errorCount++
			} else {
				warningCount++
			}
		}
		fmt.Fprint(w, "\n")
	}
	if len(failures) == 0 {
		return nil
	}
	fmt.Fprint(w, "\n")
	fmt.Fprintf(w, " %s %d problem%s (%d error%s) (%d warning%s)\n", "✖", len(failures), plural(len(failures)), errorCount, plural(errorCount), warningCount, plural(warningCount))
	return nil
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}
