// Package config holds the configuration of revive.
package config

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"

	"revive/internal/lint"
	"revive/internal/rules"
	"revive/internal/toml"
)

// Default returns the default configuration of revive.
func Default() *lint.Config {
	conf := &lint.Config{
		Severity:    "warning",
		Confidence:  0.8,
		ErrorCode:   1,
		WarningCode: 0,
		Rules:       map[string]*lint.RuleConfig{},
	}
	for _, name := range defaultRules {
		conf.Rules[name] = &lint.RuleConfig{Severity: "warning"}
	}
	return conf
}

// defaultRules are the rules that are enabled by default.
var defaultRules = []string{
	"blank-imports",
	"context-as-argument",
	"context-keys-type",
	"dot-imports",
	"error-naming",
	"error-return",
	"error-strings",
	"errorf",
	"exported",
	"increment-decrement",
	"indent-error-flow",
	"empty-block",
	"package-comments",
	"range",
	"redefines-builtin-id",
	"receiver-naming",
	"unexported-return",
	"unused-parameter",
	"unreachable-code",
	"var-declaration",
	"var-naming",
}

// Load reads the configuration of revive from the given file.
func Load(path string) (*lint.Config, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("cannot read the config file")
	}
	tree, err := toml.Parse(string(content))
	if err != nil {
		return nil, fmt.Errorf("cannot parse the config file: %v", err)
	}
	conf := Default()
	// revive reads the configuration file from scratch, so the default rules are
	// not used.
	conf.Rules = map[string]*lint.RuleConfig{}
	conf.Severity = ""
	conf.Confidence = 0
	conf.ErrorCode = 0
	conf.WarningCode = 0
	conf.Exclude = nil
	conf.EnableAllRules = false
	if err := decode(tree.Table, conf); err != nil {
		return nil, fmt.Errorf("cannot parse the config file: %v", err)
	}
	return conf, nil
}

// decode fills the given configuration with the values of the given TOML table.
func decode(table *toml.Value, conf *lint.Config) error {
	keys := make([]string, 0, len(table.Table))
	for key := range table.Table {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		value := table.Table[key]
		switch strings.ToLower(key) {
