package rules

import (
	"fmt"

	"revive/internal/lint"
)

// Configure configures the given rule with the given arguments.
func Configure(rule lint.Rule, arguments lint.Arguments) error {
	if rule, ok := rule.(*varNamingRule); ok {
		return configureVarNaming(rule, arguments)
	}
	if rule, ok := rule.(*exportedRule); ok {
		return configureExported(arguments)
	}
	return nil
}

// configureExported validates the arguments of the exported rule.
func configureExported(arguments lint.Arguments) error {
	for _, argument := range arguments {
		flag, ok := argument.(string)
		if !ok {
			return fmt.Errorf("invalid argument for the exported rule: expecting a string, got %s", typeOf(argument))
		}
		return fmt.Errorf("unknown configuration flag %s for exported rule", flag)
	}
	return nil
}

// configureVarNaming validates the arguments of the var-naming rule and loads
// the standard library packages.
func configureVarNaming(rule *varNamingRule, arguments lint.Arguments) error {
	for _, argument := range arguments {
		list, ok := argument.([]interface{})
		if !ok {
			return fmt.Errorf("invalid %d values of the var-naming rule. Expecting slice of strings but got element of type %s", len(arguments), typeOf(argument))
		}
		for _, item := range list {
			if _, ok := item.(string); !ok {
				return fmt.Errorf("invalid %d values of the var-naming rule. Expecting slice of strings but got element of type %s", len(arguments), typeOf(argument))
			}
		}
	}
	packages, err := loadStdPackages()
	if err != nil {
		return err
	}
	SetStdPackages(packages)
	return nil
}

// typeOf returns the name of the Go type of the given value.
func typeOf(value interface{}) string {
	switch value.(type) {
	case string:
		return "string"
	case int64:
		return "int64"
	case int:
		return "int"
	case float64:
		return "float64"
	case bool:
		return "bool"
	case []interface{}:
		return "[]interface {}"
	case map[string]interface{}:
		return "map[string]interface {}"
	}
	return fmt.Sprintf("%T", value)
}
GOEOF
cat > internal/rules/stdpackages.go <<'GOEOF'
package rules

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os/exec"
)

// stdPackage is the subset of the `go list -json` output that revive needs.
type stdPackage struct {
	Name       string `json:"Name"`
	ImportPath string `json:"ImportPath"`
}

// loadStdPackages returns the names of the packages of the Go standard library.
func loadStdPackages() (map[string]bool, error) {
	goCmd, err := exec.LookPath("go")
	if err != nil {
		return nil, fmt.Errorf("go command required, not found: %v", err)
	}
	// revive determines the release tags of the Go installation.
	tags, err := runGo(goCmd, "list", "-e", "-f", "{{context.ReleaseTags}}", "--", "unsafe")
	if err != nil {
		return nil, err
	}
	_ = tags
	// revive loads the packages of the standard library.
	out, err := runGo(goCmd, "list", "-e",
		"-json=Name,ImportPath,Error,Dir,GoFiles,IgnoredGoFiles,IgnoredOtherFiles,CFiles,CgoFiles,CXXFiles,MFiles,HFiles,FFiles,SFiles,SwigFiles,SwigCXXFiles,SysoFiles,CompiledGoFiles,Export",
		"-compiled=true", "-test=false", "-export=false", "-deps=false", "-find=true", "-pgo=off", "--", "std")
	if err != nil {
		return nil, err
	}
	result := map[string]bool{}
	decoder := json.NewDecoder(bytes.NewReader(out))
	for decoder.More() {
		var pkg stdPackage
		if err := decoder.Decode(&pkg); err != nil {
			break
		}
		if pkg.Name == "" {
			continue
		}
		result[pkg.Name] = true
	}
	return result, nil
}

func runGo(goCmd string, args ...string) ([]byte, error) {
	cmd := exec.Command(goCmd, args...)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("load std packages: err: %v: stderr: %v", err, stderr.String())
	}
	return out, nil
}
GOEOF
/usr/local/go/bin/go build ./internal/... 2>&1|head"}

