|_|  \___| \_/ |_| \_/ \___|

Example:
  revive -config c.toml -formatter friendly -exclude a.go -exclude b.go ./...

`

// excludeList is a list of globs that specify the files to be excluded.
type excludeList []string

func (e *excludeList) String() string {
	return strings.Join(*e, ", ")
}

func (e *excludeList) Set(value string) error {
	*e = append(*e, value)
	return nil
}

type options struct {
	config        string
	exclude       excludeList
	formatter     string
	maxOpenFiles  int
	setExitStatus bool
	version       bool
	packages      []string
}

func parseFlags() *options {
	opts := &options{}
	flag.Usage = usage
	flag.StringVar(&opts.config, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
	flag.Var(&opts.exclude, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
	flag.StringVar(&opts.formatter, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
	flag.IntVar(&opts.maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&opts.setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
	flag.BoolVar(&opts.version, "version", false, "get revive version")
	flag.Parse()
	opts.packages = flag.Args()
	return opts
}

func usage() {
	fmt.Print(banner)
	fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
	flag.PrintDefaults()
}

func main() {
	opts := parseFlags()
	if opts.version {
		fmt.Printf("Version:\t%s\n", version)
		fmt.Printf("Commit:\t\t%s\n", commit)
		fmt.Printf("Built\t\t%s\n", date)
		return
	}
	conf, err := loadConfig(opts.config)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	if len(opts.exclude) > 0 {
		conf.Exclude = append(conf.Exclude, opts.exclude...)
	}
	if opts.setExitStatus {
		conf.SetExitStatus = true
	}
	linter := &lint.Linter{MaxOpenFiles: opts.maxOpenFiles}
	lintRules, err := config.NewRules(conf)
	if err != nil {
		fmt.Printf("initializing revive - getting lint rules: %v\n", err)
		os.Exit(1)
	}
	pkgs, err := linter.GetPackages(opts.packages, conf.Exclude)
	if err != nil {
		fmt.Printf("linting - getting packages: %v\n", err)
		os.Exit(1)
	}
	fmtr, err := formatter.GetFormatter(opts.formatter)
	if err != nil {
		fmt.Printf("formatting - getting formatter: %v\n", err)
		os.Exit(1)
	}
	failures, err := linter.Lint(pkgs, lintRules, conf)
	if err != nil {
		fmt.Printf("linting - linting: %v\n", err)
		os.Exit(1)
	}
	buffer := &strings.Builder{}
	if err := fmtr.Format(failures, conf, buffer); err != nil {
		fmt.Printf("formatting - formatting: %v\n", err)
		os.Exit(1)
	}
	fmt.Print(buffer.String())
	os.Exit(exitCodeFor(failures, conf))
}

func exitCodeFor(failures []lint.Failure, conf *lint.Config) int {
	if conf.SetExitStatus {
		if len(failures) > 0 {
			return 1
		}
		return 0
	}
	code := 0
	for _, failure := range failures {
		if failure.Severity == lint.SeverityError {
			if conf.ErrorCode > code {
				code = conf.ErrorCode
			}
		} else if conf.WarningCode > code {
			code = conf.WarningCode
		}
	}
	return code
}

// loadConfig loads the configuration of revive.
func loadConfig(path string) (*lint.Config, error) {
	if path == "" {
		path = findDefaultConfigFile()
	}
	if path == "" {
		return config.Default(), nil
	}
	return config.Load(path)
}

// findDefaultConfigFile returns the path of the default configuration file of
// revive, if it exists.
func findDefaultConfigFile() string {
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		path := filepath.Join(xdg, "revive.toml")
		if fileExists(path) {
			return path
		}
	}
	if home := os.Getenv("HOME"); home != "" {
		path := filepath.Join(home, "revive.toml")
		if fileExists(path) {
			return path
		}
	}
	return ""
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !info.IsDir()
}
