		fmt.Printf("Commit:\t\t%s\n", commit)
		fmt.Printf("Built\t\t%s\n", date)
		return
	}
	conf, err := loadConfig(opts.config)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	if len(opts.exclude) > 0 {
		conf.Exclude = append(conf.Exclude, opts.exclude...)
	}
	if opts.setExitStatus {
		conf.SetExitStatus = true
	}
	linter := &lint.Linter{MaxOpenFiles: opts.maxOpenFiles}
	lintRules, err := config.NewRules(conf)
	if err != nil {
		fmt.Printf("initializing revive - getting lint rules: %v\n", err)
		os.Exit(1)
	}
	pkgs, err := linter.GetPackages(opts.packages, conf.Exclude)
	if err != nil {
		fmt.Printf("linting - getting packages: %v\n", err)
		os.Exit(1)
	}
	fmtr, err := formatter.GetFormatter(opts.formatter)
	if err != nil {
		fmt.Printf("formatting - getting formatter: %v\n", err)
		os.Exit(1)
	}
	failures, err := linter.Lint(pkgs, lintRules, conf)
	if err != nil {
		fmt.Printf("linting - linting: %v\n", err)
		os.Exit(1)
	}
	buffer := &strings.Builder{}
	if err := fmtr.Format(failures, conf, buffer); err != nil {
		fmt.Printf("formatting - formatting: %v\n", err)
		os.Exit(1)
	}
	fmt.Print(buffer.String())
	os.Exit(exitCodeFor(failures, conf))
}

func exitCodeFor(failures []lint.Failure, conf *lint.Config) int {
	if conf.SetExitStatus {
		if len(failures) > 0 {
			return 1
		}
		return 0
	}
	code := 0
	for _, failure := range failures {
		if failure.Severity == lint.SeverityError {
			if conf.ErrorCode > code {
				code = conf.ErrorCode
			}
		} else if conf.WarningCode > code {
			code = conf.WarningCode
		}
	}
	return code
}

// loadConfig loads the configuration of revive.
func loadConfig(path string) (*lint.Config, error) {
	if path == "" {
		path = findDefaultConfigFile()
	}
	if path == "" {
		return config.Default(), nil
	}
	return config.Load(path)
}

// findDefaultConfigFile returns the path of the default configuration file of
// revive, if it exists.
func findDefaultConfigFile() string {
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		path := filepath.Join(xdg, "revive.toml")
		if fileExists(path) {
			return path
		}
	}
	if home := os.Getenv("HOME"); home != "" {
		path := filepath.Join(home, "revive.toml")
		if fileExists(path) {
			return path
		}
	}
	return ""
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	return !info.IsDir()
}
