new = '''// emptyBlockRule checks for empty blocks.
type emptyBlockRule struct{}

func (*emptyBlockRule) Name() string { return "empty-block" }

func (*emptyBlockRule) Category() string { return "logic" }

func (*emptyBlockRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	failures := []lint.Failure{}
	var visit func(n ast.Node, inFunc bool)
	visit = func(n ast.Node, inFunc bool) {
		switch node := n.(type) {
		case *ast.IfStmt:
			checkEmptyBlock(file, node.Body, inFunc, &failures)
			if elseBlock, ok := node.Else.(*ast.BlockStmt); ok {
				checkEmptyBlock(file, elseBlock, inFunc, &failures)
			}
			visitChildren(node, visit, inFunc, func(child ast.Node) bool {
				return child == node.Body || child == node.Else
			})
		case *ast.ForStmt:
			checkEmptyBlock(file, node.Body, inFunc, &failures)
			visitChildren(node, visit, inFunc, func(child ast.Node) bool {
				return child == node.Body
			})
		case *ast.RangeStmt:
			checkEmptyBlock(file, node.Body, inFunc, &failures)
			visitChildren(node, visit, inFunc, func(child ast.Node) bool {
				return child == node.Body
			})
		case *ast.SwitchStmt:
			checkEmptyBlock(file, node.Body, inFunc, &failures)
			visitChildren(node, visit, inFunc, func(child ast.Node) bool {
				return child == node.Body
			})
		case *ast.TypeSwitchStmt:
			checkEmptyBlock(file, node.Body, inFunc, &failures)
			visitChildren(node, visit, inFunc, func(child ast.Node) bool {
				return child == node.Body
			})
		case *ast.SelectStmt:
			return
		case *ast.FuncDecl:
			visitChildren(node, visit, true, func(child ast.Node) bool { return false })
		case *ast.FuncLit:
			visitChildren(node, visit, true, func(child ast.Node) bool { return false })
		case *ast.BlockStmt:
			checkEmptyBlock(file, node, inFunc, &failures)
			visitChildren(node, visit, inFunc, func(child ast.Node) bool { return false })
		default:
			visitChildren(node, visit, inFunc, func(child ast.Node) bool { return false })
		}
	}
	visit(file.AST, false)
	return failures
}

// visitChildren visits the children of the given node.
func visitChildren(node ast.Node, visit func(ast.Node, bool), inFunc bool, skip func(ast.Node) bool) {
	_ = skip
	ast.Inspect(node, func(child ast.Node) bool {
		if child == node {
			return true
		}
		visit(child, inFunc)
		return false
	})
}

func checkEmptyBlock(file *lint.File, block *ast.BlockStmt, inFunc bool, failures *[]lint.Failure) {
	if block == nil || len(block.List) != 0 {
		return
	}
	if inFunc {
		return
	}
	*failures = append(*failures, lint.Failure{
		Failure:    "this block is empty, you can remove it",
		Position:   file.NodePosition(block),
		Confidence: 1,
	})
}

'''
