package rules

import (
	"go/ast"

	"revive/lint"
)

type unreachableCodeRule struct{}

// Apply applies the rule to the given file.
func (*unreachableCodeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if file.IsTest {
		return []lint.Failure{}
	}

	failures := []lint.Failure{}

	walker := lintSkipComments{
		v: &unreachableCodeVisitor{
			onFailure: func(failure lint.Failure) {
				failures = append(failures, failure)
			},
		},
	}

	ast.Walk(walker, file.AST)

	return failures
}

type unreachableCodeVisitor struct {
	onFailure func(lint.Failure)
}

func (v *unreachableCodeVisitor) Visit(node ast.Node) ast.Visitor {
	switch node := node.(type) {
	case *ast.BlockStmt:
		v.checkLast(node.List)
	case *ast.CaseClause:
		v.checkLast(node.Body)
	case *ast.CommClause:
		v.checkLast(node.Body)
	}
	return v
}

func (v *unreachableCodeVisitor) checkLast(list []ast.Stmt) {
	// revive: revive checks the statements that follow a terminating statement
	for i := 0; i < len(list)-1; i++ {
		if !isTerminating(list[i]) { continue }
		// revive: revive reports the unreachable code
		v.onFailure(lint.Failure{
			Node: list[i],
			Category: "logic",
			Confidence: 1,
			Failure: "unreachable code after this statement",
		})
	}
}

func isTerminating(stmt ast.Stmt) bool {
	switch stmt := stmt.(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.ExprStmt:
		call, ok := stmt.X.(*ast.CallExpr)
		if !ok { return false }
		return isTerminatingCall(call)
	case *ast.BranchStmt:
		return true
	case *ast.IfStmt:
		// revive: revive checks whether both branches terminate
